// Gabarito comentado — portugues (gerado). Chave: chaveQ(enunciado) em leitura/index.js.
export default {"classes":{"seo0h8":["“Rápido” modifica o verbo “trafegavam” (trafegavam de que modo? rápido = rapidamente). Quando funciona como advérbio, a palavra não concorda com nada e fica invariável.","Teste: troque por “rapidamente”. Se couber, é advérbio e não varia."],"1py6qui":["Depois de “cujo” nunca vem artigo. O certo é “O motorista cujo carro foi apreendido compareceu”. “Cujo” já carrega a ideia de posse (o carro do motorista) e concorda com a coisa possuída: cujo carro, cuja moto, cujos documentos.",""],"tkazyx":["O verbo “precisar” aqui é transitivo indireto (precisa DE algo). Verbo com preposição + “se” = índice de indeterminação do sujeito, e o verbo fica sempre no singular: “Precisa-se de agentes”, nunca “Precisam-se de agentes”.",""],"x1b69e":["“Vender” é transitivo direto (vender algo, sem preposição). VTD + “se” = partícula apassivadora: “veículos” é o sujeito paciente, e o verbo concorda com ele no plural. Equivale a “Veículos apreendidos são vendidos”.","Com preposição (precisa-se DE) = índice de indeterminação, singular. Sem preposição (vendem-se casas) = apassivadora, concorda."],"1eqlczf":["“Intervir” é derivado de “vir” e segue a conjugação dele: se ele vier → se ele intervier. A forma “se ele intervir” está errada. O mesmo vale para “convier”, “provier”, “sobrevier”.",""],"n1g1bs":["“Onde” só se refere a LUGAR físico. Para tempo ou situação, use “em que” ou “no qual”: “Foi o momento em que tudo mudou”.",""],"h51hyo":["“Bastante” modifica o adjetivo “difíceis” (difíceis em que grau? bastante = muito). Como advérbio, não varia. Já em “provas bastantes” (suficientes), é adjetivo e vai para o plural.","Troque por “muito”: se “muito” ficar invariável na frase, “bastante” também fica."],"1i4ciji":["O “que” introduz a oração que completa o verbo “disse” (disse o quê? que viria). É conjunção integrante. Teste: dá para trocar a oração por “isso” (disse isso). O pronome relativo retoma um termo anterior e pode ser trocado por “o qual”.",""],"g41bbs":["O substantivo dá nome a tudo: seres, lugares, sentimentos (saudade), ações (a corrida) e estados. É classe variável em gênero e número.",""],"umo68d":["O adjetivo indica qualidade, estado ou característica do substantivo (carro novo, rua escura) e concorda com ele em gênero e número.",""],"1ryllwm":["O advérbio indica circunstância (modo, tempo, lugar, intensidade, negação). Exemplos: “chegou cedo” (verbo), “muito bonito” (adjetivo), “muito bem” (outro advérbio).",""],"1p1ngxl":["“Meio” = “um pouco”, modificando o adjetivo “cansada”. Como advérbio, não varia: ela estava meio cansada, elas estavam meio cansadas.",""],"3zik0j":["“Meio” com sentido de “um pouco” é advérbio e invariável. O certo é “meio cansada”.",""],"cy6u0s":["Aqui “meia” significa “metade de” e acompanha o substantivo “pizza”, por isso concorda com ele: meia pizza, meio quilo, meias porções.","Metade de = varia (meia hora). Um pouco = não varia (meio tonta)."],"1pgg2u2":["Definidos (o, a, os, as) indicam ser específico; indefinidos (um, uma, uns, umas) indicam ser qualquer.",""],"1yvlc92":["Pronome substantivo substitui (“Ele chegou”); pronome adjetivo acompanha (“Meu carro”). Tipos: pessoais, possessivos, demonstrativos, indefinidos, interrogativos e relativos.",""],"1t7rrit":["Cardinal (dois), ordinal (segundo), multiplicativo (dobro) e fracionário (metade, um terço).",""],"or51v8":["Ação (correr), estado (estar, ficar) e fenômeno da natureza (chover). É a classe com mais flexões: tempo, modo, número, pessoa e voz.",""],"y2rytm":["A preposição liga duas palavras, e a segunda depende da primeira: “casa DE madeira”, “gosto DE café”. Principais: a, ante, até, com, contra, de, desde, em, entre, para, por, sem, sob, sobre.",""],"h9tcn8":["Coordenativas ligam termos ou orações independentes (e, mas, ou, portanto). Subordinativas ligam uma oração dependente à principal (que, porque, embora, se).",""],"180ykof":["A interjeição vale por uma frase inteira e expressa emoção: alegria (Oba!), alívio (Ufa!), dor (Ai!), espanto (Nossa!).",""],"15iy4e6":["Essas quatro não flexionam em gênero ou número. As variáveis são substantivo, adjetivo, artigo, pronome, numeral e verbo.",""],"sgxqfj":["É a derivação imprópria: a palavra muda de classe sem mudar de forma. “O não dele”, “o jantar”, “um sim”.",""],"1w52zyb":["Retos (eu, tu, ele, nós, vós, eles) são sujeito: “Eu saí”. Oblíquos (me, mim, te, ti, o, a, lhe, se, si, nos, vos) são complemento: “Ele me viu”.",""],"vepbaz":["Quem vai fazer? Eu. Como o pronome é o SUJEITO do verbo no infinitivo “fazer”, deve ser reto: “Isso é para eu fazer”. “Mim” não faz nada, porque não pode ser sujeito.",""],"ypbsje":["Aqui não há verbo depois do pronome. “Mim” é complemento da preposição “para”, e depois de preposição usa-se o oblíquo tônico: para mim, sem mim, contra mim.","“Para mim” + infinitivo é errado quando o pronome é o sujeito do verbo. Mas “Para mim, fazer isso é fácil” está certo (a vírgula mostra que “mim” não é sujeito)."],"16n2uwd":["Demonstrativos situam o ser no espaço, no tempo ou no texto em relação às pessoas do discurso. Também são demonstrativos isto, isso, aquilo e suas variações.",""],"dlf8um":["Este (aqui, perto de mim), esse (aí, perto de você), aquele (lá, longe dos dois).",""],"11jpmf1":["“Este” é catafórico (aponta para frente): “Meu pedido é este: silêncio”. “Esse” é anafórico (retoma o que veio antes): “Silêncio: esse foi o pedido”.",""],"9bpnmi":["“Cujo” liga o possuidor à coisa possuída e concorda com a coisa possuída: “o autor cujo livro li” (o livro do autor). Nunca aceita artigo depois.",""],"tva8o6":["Não se usa artigo após “cujo”. O certo é “O autor cujo livro li é famoso”.",""],"1hcxjw2":["“A cidade onde moro”, “a casa onde nasci”. Para tempo ou situação, use “em que”.",""],"chq6ca":["Indica como ele saiu. Muitos advérbios de modo terminam em “-mente”, formados a partir do adjetivo no feminino (rápida + mente).",""],"1ceffxr":["É um grupo de palavras (preposição + substantivo) que funciona como adjetivo: anel de ouro (áureo), amor de mãe (materno), água da chuva (pluvial).",""],"q8wlyr":["Com valor de “próprio”, “mesmo” é adjetivo e concorda: elas mesmas, ele mesmo. Com valor de “realmente” ou “até”, é advérbio e não varia: “Elas vieram mesmo”.",""],"1bwflar":["Com valor de “suficiente(s)”, acompanha o substantivo e concorda: “Há provas bastantes para condenar”. Com valor de “muito”, modificando adjetivo ou verbo, é advérbio e invariável.",""],"rv43zz":["Verbo de ligação não indica ação, mas estado, e liga o sujeito à sua característica (predicativo): “O motorista estava cansado”. Outros: permanecer, ficar, continuar, andar (no sentido de estar).",""],"1pp7ovk":["Na passiva sintética, o “se” é partícula apassivadora e o verbo concorda com o sujeito paciente: “Vendem-se casas” = “Casas são vendidas” (passiva analítica).",""],"p9qxo2":["Advérbio: modifica outro advérbio (“cedo”).","",["Seria adjetivo se significasse “suficiente” e acompanhasse substantivo.","Correta.","Não substitui nem acompanha substantivo.","Não nomeia nada.","Não liga termos."]],"kqx30o":["“O aluno cujo pai veio...”, sem artigo após “cujo”.","",["Artigo após “cujo” é erro.","Correta.","“Que o pai” é o “queísmo” popular, errado na norma.","“Cujo do” não existe.","“De cujo” só se o verbo pedir a preposição “de”."]],"ppxz6u":["“Cujo” e suas flexões.","",["“Que” não indica posse.","“Onde” indica lugar.","Correta.","“Quem” se refere a pessoa.","“Qual” não indica posse."]],"lr21c8":["O adjetivo varia em gênero e número.","",["É invariável.","É invariável.","É invariável.","É invariável.","Correta."]],"1xokhgp":["Substantivo, pela presença do artigo “o”.","",["Normalmente é advérbio, mas o artigo o substantivou.","Correta.","Não liga orações.","Não liga termos.","Não exprime emoção."]],"9w0q9o":["Interjeição de alívio.","",["Não modifica verbo.","Não liga orações.","Não liga termos.","Correta.","Não substitui substantivo."]],"1ju7b7e":["“Esse” (uso anafórico).","",["“Este” anuncia o que vai ser dito.","Correta.","“Aquele” não é sempre usado para retomar.","“Isto” também anuncia.","“Tal” não é a regra."]],"qqfbog":["Passiva sintética: VTD + “se”.","",["Não é ativa: os apartamentos sofrem a ação.","Analítica seria “são vendidos”.","Correta.","Os apartamentos não vendem a si mesmos.","Não há ação mútua."]],"7zvl36":["“Próprias”.","",["Com sentido de “até”, seria invariável.","Correta.","Com sentido de “ainda”, não varia.","Com sentido de “realmente”, não varia.","Não equivale a “também”."]],"1k58of3":["Preposição.","",["A conjunção liga orações ou termos de mesma função.","Correta.","Interjeição exprime emoção.","Artigo determina o substantivo.","Numeral indica quantidade."]]},"coesao":{"1u3yz5j":["Concessão é admitir um obstáculo que não impede o fato principal: a via estava interditada (obstáculo), mas os motoristas tentaram passar mesmo assim. “Embora” pede o verbo no subjuntivo (estivesse).","Concessivas: embora, ainda que, mesmo que, conquanto, posto que, se bem que."],"fpz49s":["“Porém” indica oposição (estava habilitado, MAS sem documento). “Portanto” indica conclusão. Trocar um pelo outro muda o sentido e deixa a frase sem lógica.",""],"blhpgw":["O futuro do pretérito usado assim marca distanciamento: o jornalista relata a informação sem se comprometer com ela, porque ainda não está confirmada.",""],"xva7gz":["Depois de “se” (condição), usa-se o subjuntivo: “Se o condutor tivesse parado, não haveria acidente”. O futuro do pretérito (“haveria”) fica na oração principal, nunca na oração com “se”.",""],"1whsxzo":["Em enumeração, “este(s)” retoma o termo mais próximo (condutores) e “aquele(s)” retoma o mais distante (agentes).",""],"1ulktk":["“À medida que” = proporção (à medida que estudava, aprendia). “Na medida em que” = causa (na medida em que faltou, foi punido = porque faltou).","Não existe “à medida em que”: é mistura das duas formas e está errado."],"phwaam":["É o futuro do subjuntivo do verbo VER: quando eu vir, quando nós virmos, quando eles virem. “Quando eu ver” está errado.",""],"jjhr8z":["“Conquanto” é concessivo e equivale a “embora”: “Conquanto estivesse cansado, continuou”.",""],"17a93y1":["Coesão é a amarração gramatical: conectores (mas, portanto), pronomes que retomam (ele, este), sinônimos, elipses. Ela é visível na superfície do texto.",""],"akuo8l":["Coerência é o texto fazer sentido como um todo, sem contradições. Um texto pode ter conectores (coesão) e ainda ser incoerente.",""],"pe3nas":["Exemplo: “O agente chegou. Ele pediu os documentos.” O pronome “ele” retoma “o agente”.",""],"6npyk2":["Anáfora olha para trás (retoma). Catáfora olha para frente (antecipa): “Só quero isto: respeito”.",""],"lrl0ym":["“Isto” aponta para o que vem depois dos dois-pontos (“não voltarei”). Por isso é catafórico.",""],"cevhu8":["É a conjunção coordenativa adversativa típica, junto com porém, contudo, todavia, entretanto e no entanto.",""],"j1ra5h":["São conjunções coordenativas conclusivas. Também: pois (depois do verbo), então, assim, por isso.",""],"f5joaa":["Introduzem a razão do fato principal: “Foi multado porque avançou o sinal”. Também: uma vez que, como (no início da frase).",""],"15wzdjv":["As concessivas apresentam um obstáculo que não impede o fato principal e levam o verbo ao subjuntivo: “Embora chovesse, saiu”.",""],"1tmpuvn":["Indicam o objetivo da ação principal: “Estudou para que fosse aprovado”.",""],"e2u1pd":["Indicam a condição para o fato principal: “Caso chova, o jogo será adiado”.","“Desde que” também pode ser temporal: “Desde que chegou, trabalha muito”."],"109j6sk":["Indicam acordo com algo: “Conforme a lei determina, o veículo foi removido”.",""],"17bne2w":["Indicam que um fato aumenta ou diminui junto com outro: “À medida que a velocidade aumenta, cresce o risco”.",""],"1d55ow0":["“Na medida em que” é causal; “à medida que” é proporcional.",""],"130ymwx":["Todas equivalem a “mas” e podem ser trocadas entre si sem mudar o sentido.",""],"t5lrw1":["As duas são adversativas. Atenção à pontuação: “porém” pode vir deslocado e entre vírgulas (“Estudou, porém, não passou”), o que “mas” não admite.",""],"1l7kupv":["“Embora” é concessão; “porque” é causa. Exemplo: “Embora chovesse, saiu” (saiu apesar da chuva) é diferente de “Porque chovia, saiu”.",""],"r1flru":["Exemplo: “Ontem eu estudei”. A ação começou e terminou.",""],"1earrvk":["Exemplo: “Quando criança, eu estudava à noite” (hábito) ou “Eu estudava quando ele chegou” (em andamento).",""],"1ol8x8l":["Exemplo: “Quando cheguei, ele já saíra” (= já tinha saído). A saída aconteceu antes da chegada, e as duas no passado.",""],"12x0nqd":["Exemplo: “Se tivesse tempo, eu estudaria”. Também indica cortesia (“Você poderia me ajudar?”) e incerteza em notícias.",""],"1864crp":["Exemplo: “Talvez ele venha”, “Espero que você passe”. É o modo do incerto, ao contrário do indicativo, que é o modo da certeza.",""],"jqohwm":["Exemplos: “Estude todos os dias”, “Não use o celular ao volante”.",""],"xxvlq4":["A combinação correta é: imperfeito do subjuntivo (tivesse) + futuro do pretérito (viajaria). É a correlação para hipóteses.",""],"1c20y30":["A combinação correta é: futuro do subjuntivo (chegar) + futuro do presente (avisarei). É a correlação para fatos futuros possíveis.","“Se eu tivesse... faria” (hipótese). “Se eu tiver... farei” (possibilidade futura)."],"1c2qoa0":["O futuro do subjuntivo de “ter” é “tiver”: “Se eu tiver tempo, irei”.",""],"abctic":["Ver: quando eu vir, tu vires, ele vir, nós virmos, vós virdes, eles virem.",""],"4g3u":["Vir: quando eu vier, tu vieres, ele vier, nós viermos, eles vierem. Não confundir com o futuro de “ver” (vir).",""],"13f9cki":["“Manter” segue “ter”: se ele tiver → se ele mantiver. Valem também deter (detiver), obter (obtiver), conter (contiver).",""],"1jc773t":["Exemplo: “O agente parou o carro e (ele) pediu os documentos”. A omissão evita repetição e mantém a ligação.",""],"jnvnkj":["“Portanto”: a aprovação é conclusão do estudo.","",["“Contudo” indica oposição, sem lógica aqui.","Correta.","“Embora” é concessivo e pede subjuntivo.","“Porque” inverteria a lógica (causa).","“Caso” é condicional."]],"sejv8j":["“Embora”.","",["“Porque” é causal.","Correta.","“Logo” é conclusiva.","“Quando” é temporal.","“Pois” é causal ou explicativa (ou conclusiva depois do verbo)."]],"kqimsa":["“A fim de que”.","",["“Porque” é causal.","Correta.","“Embora” é concessivo.","“Logo” é conclusivo.","“Conforme” é conformativo."]],"l5l5ry":["Proporção.","",["Causa seria “na medida em que”.","Correta.","Concessão seria “embora”.","Finalidade seria “para que”.","Condição seria “se”."]],"12qnf2k":["“Quando eu vir o resultado”: futuro do subjuntivo de “ver”.","",["“Ver” é o infinitivo, não o futuro do subjuntivo.","Correta.","“Vier” é do verbo “vir”.","Futuro do presente não cabe depois de “quando”.","O passado não combina com “aviso”."]],"8r1qpm":["“Mantiver”: futuro do subjuntivo de “manter”.","",["“Manter” é o infinitivo.","Correta.","“Manteu” não existe.","“Mantesse” não existe; seria “mantivesse”.","Presente do indicativo não combina com “se” + “resolverá”."]],"qzl6cw":["Pretérito mais-que-perfeito.","",["O perfeito é ação concluída.","O imperfeito é ação habitual ou em curso.","Correta.","O futuro do pretérito é hipótese.","O presente é o agora."]],"f1z0gb":["“Entretanto”, também adversativa.","",["“Portanto” é conclusiva.","Correta.","“Porque” é causal.","“Assim” é conclusiva.","“Logo” é conclusiva."]],"1awyh11":["Catafórica.","",["Anafórica retoma.","Correta.","Dêitica aponta para a situação, fora do texto.","Expletiva é de realce.","Reflexiva indica ação sobre o próprio sujeito."]],"1szlum2":["“Tivesse”: imperfeito do subjuntivo combina com o futuro do pretérito.","",["Presente não combina com “se” + “compraria”.","“Tiver” combina com “comprarei”.","Correta.","Futuro não cabe depois de “se”.","“Tinha” é informal; a norma pede “tivesse”."]],"vcbtf9":["Causa.","",["Proporção é “à medida que”.","Correta.","Não é concessão.","Não é tempo.","Não é finalidade."]],"1nbfkan":["Conformidade.","",["Não é causa.","Correta.","Não é concessão.","Não é condição.","Não é consequência."]]},"colocacao":{"6yshq1":["“Ninguém” é pronome indefinido com sentido negativo, e palavras negativas puxam o pronome átono para antes do verbo (próclise). “Ninguém avisou-o” está errado.","Palavras que atraem o pronome: negativas, relativos, indefinidos, demonstrativos, conjunções subordinativas, advérbios sem vírgula e interrogativos."],"1tswfd2":["Na norma-padrão escrita, não se começa a oração com pronome oblíquo átono. O certo é “Entregaram-me a notificação ontem”. Na fala do Brasil isso é comum, mas a prova cobra a norma escrita.",""],"1py5nwx":["O verbo está no futuro do presente (realizará) e não há palavra atrativa antes dele. Nesse caso, a norma pede mesóclise: o pronome entra no meio do verbo (realizar-se-á). Ênclise com futuro (“realizará-se”) é sempre erro.",""],"lnip8b":["O pronome nunca fica depois do particípio. Na locução com particípio, o pronome vai junto ao verbo auxiliar: “Ele tinha-se ferido” ou “Ele se tinha ferido”. (No Brasil, também se aceita “tinha se ferido”, sem hífen.)",""],"1q55k3d":["“Quando” é conjunção subordinativa (temporal) e atrai o pronome para antes do verbo: “Quando o viram”.",""],"1ftyqku":["Há duas falhas: ênclise com futuro (proibida) e a presença do “não”, que obriga a próclise. O certo é “Não se realizará a operação”.",""],"ntow1s":["Quando o verbo termina em r, s ou z e recebe o pronome “o/a”, a última letra do verbo cai e o pronome vira “lo/la”: respeitar + o = respeitá-lo; fiz + o = fi-lo; amamos + o = amamo-lo.",""],"yuwdcp":["O advérbio só atrai o pronome quando não há vírgula depois dele. Com a vírgula, a atração some, e volta a regra de não começar a oração com pronome: “Ontem, ligaram-me do posto”.",""],"1tj8y42":["“Pró” = antes. Exemplo: “Não me ligue”.",""],"1yd0djj":["É a colocação padrão quando não há palavra atrativa. Exemplo: “Ligue-me amanhã”.",""],"1c92086":["Só acontece no futuro do presente (far-se-á) e no futuro do pretérito (far-se-ia), quando não há fator de próclise.",""],"7lm65s":["Exemplos: “Não o vi”, “Nunca me disseram”, “Ninguém nos contou”.",""],"17gtarh":["“Que”, “o qual”, “quem”, “cujo”, “onde” atraem: “O livro que me deste”, “A rua onde se mora”.",""],"d53x6n":["“Quando”, “se”, “que”, “embora”, “porque” e outras atraem: “Quando me chamaram, saí”.",""],"6edebp":["“Aqui se trabalha”, “Sempre me lembro”. Com vírgula, a atração some: “Aqui, trabalha-se”.",""],"82p47l":["“Tudo se resolveu”, “Alguém me ligou”, “Todos o viram”.",""],"1f8dqmr":["Oração optativa expressa desejo: “Deus te abençoe!”, “Bons ventos o levem!”.",""],"2d56og":["Por isso “Me dá” vira “Dê-me” e “Me empresta” vira “Empreste-me”.",""],"1eu67bk":["Começa com pronome átono. Na norma escrita: “Empreste-me o livro”.",""],"1sgb0hu":["Futuro do presente: entregarei → entregar-lhe-ei.",""],"u0ho2f":["Nunca há ênclise com verbo no futuro. As opções corretas são “Entregar-lhe-ei” (mesóclise) ou, havendo atrativa, “Não lhe entregarei” (próclise).",""],"1j9d7wz":["A próclise tem prioridade sobre as outras colocações. “Não lhe entregarei”, e não “Não entregar-lhe-ei”.",""],"tyb167":["Com infinitivo precedido de preposição, as duas posições são aceitas: “para o encontrar” ou “para encontrá-lo”. Com “não” antes do infinitivo, a próclise é preferível, mas a ênclise também é aceita.",""],"v3vo3n":["O particípio nunca recebe o pronome depois dele. Na locução, o pronome vai com o auxiliar: “Tinha-lhe dado” ou “Lhe tinha dado” (se houver atrativa).",""],"39u0cy":["“Vou fazê-lo” ou “Vou-o fazer”. A ênclise ao infinitivo é a forma mais usada.",""],"98sk1y":["“Saiu, deixando-nos sós”. Se houver atrativa (como “não”), usa-se próclise: “Saiu, não nos deixando escolha”.",""],"1bs4egp":["A letra final cai e o pronome vira “lo”: vender + o = vendê-lo; fazer + o = fazê-lo.",""],"1e21m3c":["Verbo terminado em -m, -ão, -õe recebe “no/na”: dão + o = dão-no; põe + o = põe-no; fazem + o = fazem-no.",""],"insrxf":["Verbo terminado em r + “o” vira “-lo”, e o “r” cai: “Vou fazê-lo”.",""],"149tz3j":["O advérbio de negação “não” atrai o pronome.",""],"g77l93":["Com a vírgula, o advérbio fica isolado e deixa de atrair. Sem a vírgula, o correto seria “Aqui se trabalha muito”.",""],"7dieio":["“Que” é conjunção integrante (subordinativa) e atrai o pronome.",""],"19wjtmc":["Imperativo afirmativo no início da oração pede ênclise: “Diga-me”, “Faça-o”. No imperativo negativo, há próclise por causa do “não”: “Não me diga”.",""],"s4yz96":["“Isso me preocupa”, “Aquilo o assustou”.",""],"8uj987":["Futuro do pretérito: diria → dir-se-ia.",""],"twstt5":["Com o futuro no início da oração, só a mesóclise é aceita: não pode ênclise (futuro) nem próclise (início de oração).",""],"19tnhcx":["“Ninguém” é indefinido e tem sentido negativo: as duas razões atraem o pronome.",""],"f7j8fg":["Na fala é comum dizer “Me dá um café”. Na escrita formal (e na prova), a regra é não começar a oração com pronome átono.",""],"lqn9sw":["“Diga-me a verdade”: imperativo afirmativo no início, com ênclise.","",["Começa com pronome átono.","Correta.","O pronome não pode ficar longe do verbo.","Repete o pronome.","Mistura tempos sem sentido."]],"kqx30o":["“Tudo se resolveu”: o indefinido atrai.","",["Com atrativa, não cabe ênclise.","Correta.","Começa com pronome átono e muda a ordem.","Ordem errada.","Ênclise sem hífen, com atrativa."]],"1yaun72":["“Põe-no aqui”: verbo com som nasal + “o” vira “no”.","",["Depois de som nasal, o pronome muda para “no”.","Correta.","“Lo” é para verbo terminado em r, s, z.","Falta hífen e a forma “no”.","“Lho” é “lhe + o”, outro sentido."]],"c9niy1":["O pronome interrogativo “quem”.","",["O verbo não atrai.","Correta.","Não há vírgula.","O tempo verbal não obriga próclise.","Não há sujeito oculto: “quem” é o sujeito."]],"1qm301h":["Próclise nos dois casos: “me” depois do pronome reto “ele” e “se” depois da conjunção “que”.","",["Não há ênclise.","Correta.","“Casaria” poderia ter mesóclise, mas a conjunção “que” atrai o pronome.","Não há ênclise nem mesóclise.","A colocação está correta."]],"1rbps7f":["Futuro do presente ou do pretérito.","",["Presente não admite mesóclise.","Perfeito não admite mesóclise.","Correta.","Imperativo não admite mesóclise.","Gerúndio não admite mesóclise."]],"djy4l":["A vírgula depois do advérbio quebra a atração.","",["O advérbio existe.","Correta.","O verbo está no presente.","Não há negação.","Não há conjunção."]]},"concordancia":{"h83nyx":["“Haver” no sentido de existir é impessoal (não tem sujeito) e fica no singular. Quando entra numa locução, passa essa impessoalidade para o verbo auxiliar: “Deve haver soluções”. Com “existir”, que tem sujeito, seria “Devem existir soluções”.","Haver = existir → singular, inclusive o auxiliar (deve haver, pode haver, vai haver)."],"1oap2gr":["“Aplicar” é transitivo direto, e o “se” é partícula apassivadora (passiva sintética). “Várias multas” é o sujeito paciente, e o verbo concorda com ele: “Aplicaram-se várias multas” = “Várias multas foram aplicadas”.",""],"e4rkb2":["Com “mais de um”, o verbo fica no singular, concordando com “um”. O plural só é obrigatório se houver ideia de reciprocidade (“Mais de um condutor se agrediram”) ou se a expressão vier repetida.",""],"1hcvzjf":["“Precisar de” é transitivo indireto. Com preposição, o “se” é índice de indeterminação do sujeito e o verbo fica no singular: “Precisa-se de mais agentes”.",""],"192yytu":["Nas expressões “é proibido”, “é necessário”, “é bom”, o adjetivo concorda com o substantivo quando ele vem determinado (por artigo, pronome): “É proibida a entrada”. Sem determinante, fica invariável: “É proibido entrada”.",""],"1upa7ph":["“Anexo” é adjetivo e concorda com o substantivo: “Seguem anexas as fotografias”. A outra opção correta é a locução invariável “em anexo”: “Seguem em anexo as fotografias”.",""],"1qcyob2":["Indicando data, o verbo “ser” concorda com o número de dias: “Hoje são 3 de novembro”. Se a palavra “dia” estiver explícita, concorda com ela: “Hoje é dia 3 de novembro”.",""],"rd520p":["“Existir” tem sujeito, e o sujeito aqui é “muitas irregularidades”. O verbo deve ir para o plural: “Existem muitas irregularidades”.",""],"17rr13w":["É a regra geral da concordância verbal: “Eu cheguei”, “Nós chegamos”, “Os agentes chegaram”.",""],"10ofr0i":["Exemplo: “O agente e o perito chegaram”.",""],"fmezb0":["Exemplo: “Chegou o agente e o perito” ou “Chegaram o agente e o perito”. As duas formas são aceitas.",""],"179j12w":["Exemplo: “Houve problemas”, “Havia muitas pessoas”, “Haverá vagas”.",""],"1fjablt":["“Existir”, “ocorrer” e “acontecer” têm sujeito e concordam com ele: “Existem problemas”, “Ocorreram acidentes”.",""],"18jpi74":["“Haver” = existir é impessoal: “Houve muitas reclamações”.",""],"6n7wvy":["Exemplo: “Vendem-se casas” (casas são vendidas), “Aluga-se uma sala” (uma sala é alugada).",""],"17lk7tj":["“Alugar” é transitivo direto: o “se” é apassivador e “apartamentos” é o sujeito. O certo é “Alugam-se apartamentos” (apartamentos são alugados).",""],"ek3nx2":["Com verbo transitivo indireto (com preposição), intransitivo ou de ligação + “se”, o verbo fica no singular: “Precisa-se de técnicos”, “Vive-se bem aqui”.",""],"1kahylc":["Com expressões partitivas (a maioria de, grande parte de, metade de) seguidas de plural, o verbo pode concordar com o núcleo (“a maioria faltou”) ou com o especificador (“a maioria dos alunos faltaram”).",""],"cw2h7f":["Exemplo: “Mais de um candidato faltou”. Já “mais de dois” leva o verbo ao plural: “Mais de dois candidatos faltaram”.",""],"8on4bu":["O “que” retoma “eu”, então o verbo vai para a 1ª pessoa: “Fui eu que paguei”, “Fomos nós que pagamos”.",""],"hmgpg":["Com “quem”, o verbo pode concordar com o próprio “quem” (3ª pessoa: “Fui eu quem pagou”) ou com o antecedente (“Fui eu quem paguei”). As duas são aceitas.",""],"14ycb45":["Com artigo no plural, o verbo vai ao plural: “Os Estados Unidos enviaram”. Sem artigo, fica no singular: “Estados Unidos enviou”.",""],"1yq5dh8":["“São dez horas”, “É uma hora”, “É meio-dia”.",""],"1cc4mib":["Exemplos: “30% dos alunos faltaram” ou “1% dos eleitores votou” (com o número) e “1% dos eleitores votaram” (com o especificador). Se o número vier determinado (“Os 30% ...”), concorda com ele.",""],"11soxu9":["Exemplo: “carro e moto nova” ou “carro e moto novos”. Com substantivos de gêneros diferentes, o plural vai para o masculino.",""],"1wpj2us":["Exemplo: “Escolheu bonita casa e jardim”. Se os substantivos forem nomes de pessoas, o adjetivo vai ao plural: “as simpáticas Ana e Maria”.",""],"71y3mc":["São adjetivos: “As cópias seguem anexas”, “A taxa está inclusa”, “Muito obrigada” (dito por mulher).",""],"hwsqpu":["Com a preposição “em”, vira locução adverbial e não varia: “Seguem em anexo as cópias”.",""],"mjws1a":["“Menos” é advérbio ou pronome invariável. A forma “menas” não existe na língua.",""],"3q608m":["Sem artigo ou outro determinante, a expressão fica no masculino singular, com sentido genérico.",""],"1u2c7sn":["Com o artigo “a”, o adjetivo concorda com “entrada”.",""],"1hnbzsu":["Com o artigo “a”, o adjetivo deve concordar: “É necessária a presença de todos”.",""],"l0gbad":["Com sentido de “suficientes”, acompanha o substantivo e concorda: “Há provas bastantes”.",""],"1k6521q":["“Ela está meio nervosa” (um pouco nervosa).",""],"1pyaupu":["“Elas estavam sós” (sozinhas). A expressão “a sós” é invariável: “Ficaram a sós”.",""],"5p6ppu":["“Só elas vieram” (somente elas).",""],"14ai44y":["“Quite” é adjetivo: “Estou quite”, “Estamos quites”.",""],"r741r5":["Indicando tempo decorrido ou clima, “fazer” não tem sujeito e fica no singular: “Faz dez dias”, “Faz meses que não chove”. Na locução, o auxiliar também fica no singular: “Vai fazer dez anos”.",""],"kqx30o":["“É necessário paciência”: sem determinante, a expressão fica invariável.","",["Correta.","Sem artigo, não se faz a concordância.","Verbo no plural sem motivo.","Repete o verbo.","Sem concordância."]],"2mdugg":["“São duas horas”: o verbo concorda com o numeral.","",["“É” no singular não concorda com “duas horas”.","Correta.","“Era” no singular é erro; seria “Eram duas horas”.","“Foi” no singular é erro.","Não há artigo antes das horas nesse caso."]]},"crase":{"w3h6nm":["Crase é a junção da preposição “a” com o artigo feminino “a”. Verbo nunca recebe artigo (não se diz “a verificar” com artigo), por isso não há crase antes de verbo: “começou a verificar”.","Antes de verbo, palavra masculina, pronome pessoal e a maioria dos pronomes de tratamento: nunca crase."],"uz4xs5":["Antes de pronome possessivo feminino no singular (sua, minha, nossa), o artigo é opcional (“a sua chefe” ou “sua chefe”). Por isso a crase também é opcional: “à sua chefe” ou “a sua chefe”.",""],"1jlhv3p":["Teste para lugares: troque “ir a” por “voltar de”. Se ficar “volto DA”, há artigo e há crase (vou à Bahia). Se ficar “volto DE”, não há artigo e não há crase (vou a Brasília).","“Vou a, volto da, crase há. Vou a, volto de, crase pra quê?”"],"ihz0fw":["Os pronomes de tratamento com “Vossa” (Vossa Excelência, Vossa Senhoria) não aceitam artigo. Sem artigo, não há crase: “a Vossa Excelência”. As exceções são “senhora”, “senhorita” e “dona” (às vezes), que aceitam artigo.",""],"1ltuvgz":["Horas determinadas pedem artigo (as 17h), e o “a” da preposição se funde com ele. Como começa com “das” (de + as), o par é “das... às”. Se começasse com “de” sem artigo, seria “de 9h a 17h”.",""],"1j7u35a":["“Pedido” é palavra masculina e não aceita artigo feminino. Sem artigo “a”, não há crase: “a pedido do delegado”.",""],"1jiq2d6":["Quem se refere, se refere A algo. A preposição “a” se funde com o “a” inicial de “aquela”: a + aquela = àquela. O mesmo ocorre com aquele (àquele) e aquilo (àquilo).",""],"1gvwq0k":["Em expressões com palavras repetidas (frente a frente, cara a cara, gota a gota, dia a dia), o “a” é só preposição, sem artigo. Não há crase.",""],"18xbirb":["É a definição. Para haver crase, precisa existir ao mesmo tempo a preposição (pedida por uma palavra anterior) e o artigo (aceito pela palavra seguinte, feminina).","Teste rápido: troque a palavra feminina por uma masculina. Se aparecer “ao”, há crase: “Fui à praia” → “Fui ao clube”."],"1vti8dl":["Palavra masculina não aceita o artigo “a”. Exemplos: “andou a cavalo”, “a pé”, “a prazo”. Exceção: quando está subentendida a expressão “à moda de” (“bife à milanesa”, “vestir-se à Luís XV”).",""],"1j4bgn5":["Verbo não aceita artigo. Exemplo: “Começou a estudar”, “Estou disposto a ajudar”.",""],"wp2d8q":["Pronomes pessoais (ela, você) e de tratamento com “Vossa” não aceitam artigo: “Entreguei a ela”, “Encaminho a Vossa Excelência”.",""],"rpu9n2":["“Senhora” e “senhorita” aceitam artigo (a senhora). Com verbo que pede preposição “a”, há crase: “Entreguei à senhora”.",""],"17vm1ad":["Cara a cara, frente a frente, ponta a ponta: o “a” é só preposição.",""],"i8591x":["Se o “a” está no singular e a palavra no plural, ele é só preposição (não há artigo “a” antes de plural): “Refiro-me a pessoas honestas”. Com artigo, seria “às pessoas”.",""],"z9uaog":["Exemplos: às vezes, à noite, à tarde, às pressas, à vontade, às claras.",""],"5bczj9":["Exemplos: à custa de, à espera de, à frente de, à medida que, à proporção que.",""],"n8lnlp":["Exemplo: “Chegou às oito horas”, “à uma hora”. Atenção: “há” com h é do verbo haver (tempo passado): “Saiu há duas horas”.",""],"1nhq64l":["Começa A QUE HORAS? Às 9 horas. Horas determinadas pedem crase.",""],"1wb5aac":["Mesmo antes de palavra masculina: “bife à milanesa” (à moda milanesa), “gol à Pelé” (à moda de Pelé).",""],"18o2cpv":["Exemplos: “Vou à Bahia” (volto da Bahia), “Vou a Brasília” (volto de Brasília). Se o lugar vier especificado, aceita artigo: “Vou à Brasília dos anos 60”.",""],"1ec61jh":["O nome “Bahia” aceita artigo (a Bahia), por isso há crase.",""],"1wbto53":["Nomes de cidades, em geral, não aceitam artigo. Sem artigo, não há crase.",""],"1xaztjt":["“Casa” como o próprio lar, sem complemento, não leva artigo: “Voltei a casa”, “Cheguei a casa cedo”.",""],"1v2ov7u":["Com especificação (de quem é a casa), aceita artigo: “Voltei à casa dos meus pais”.",""],"1aqjgye":["“Terra” oposta a bordo (para quem está no mar ou no ar) não leva artigo. Se for terra específica ou o planeta, há crase: “Voltou à terra natal”.",""],"1hry2nv":["“Ensino a distância” (não especificada), mas “à distância de dez metros” (especificada).",""],"12ojwoc":["Basta que a palavra anterior peça a preposição “a”: “Refiro-me àquele caso”, “Não dei atenção àquilo”.",""],"1cdthvy":["O artigo antes do possessivo é opcional, por isso a crase também é.",""],"702dkb":["Antes de nome de pessoa, o artigo é opcional (“a Maria” ou “Maria”). A crase acompanha essa opção. Com nome de pessoa famosa ou histórica, em regra, não se usa artigo.",""],"19jpjy0":["“Até” pode vir sozinha ou acompanhada de “a” (até a). Por isso: “Fui até a escola” ou “Fui até à escola”.",""],"14wm6lb":["“Ajudar” é verbo, que não aceita artigo. Não há crase.",""],"1t3d8m6":["“Vossa Senhoria” não aceita artigo. O certo é “Fez referência a Vossa Senhoria”.",""],"18u1pcl":["Quem se dirige, se dirige A alguém; “diretora” aceita artigo (a diretora). A + a = à. Teste: “Dirigiu-se ao diretor”.",""],"5c530v":["Com o artigo indefinido “uma”, não há artigo definido “a” para se fundir com a preposição.",""],"13bpvzc":["Com “de” (sem artigo) no início, o par fica sem artigo: “de... a”.",""],"1ext8z2":["Com “da” (de + a) no início, o par segue com artigo: “da... à”.","Mantenha o paralelismo: de... a; da... à; das... às."],"d42cmy":["“Alusão” pede a preposição “a” (alusão a algo), e “proposta” aceita artigo (a proposta). A + a = à.",""],"lw10sp":["“Chegou às dez horas”: hora determinada.","",["“Pé” é masculino.","“Chover” é verbo.","Correta.","“Ela” é pronome pessoal.","Palavras repetidas."]],"1l2ufvd":["“Entreguei o ofício a Vossa Excelência”: pronome de tratamento não aceita artigo.","",["Há crase (vou à, volto da farmácia).","Há crase com “aquela”.","Correta.","Locução adverbial feminina.","Casa especificada."]],"8yxlec":["“Vou à Bahia”: volto da Bahia.","",["Volto de Brasília: sem crase.","Volto da Bahia: precisa de crase.","Correta.","Volto de Portugal: sem crase.","Volto de Belo Vale: sem crase."]],"1asmnjx":["“Entreguei a carta à Joana”: nome próprio feminino.","",["Obrigatória: “senhora” aceita artigo.","Correta.","Obrigatória: hora determinada.","Obrigatória: volto da praia.","Obrigatória: assistir a + a peça."]],"kqx30o":["“Estou disposto a colaborar”: antes de verbo não há crase.","",["Crase antes de verbo é erro.","Correta.","Crase antes de verbo é erro.","Crase antes de adjetivo masculino é erro.","O acento agudo (á) não existe nesse caso."]],"1jt1tc2":["“a”: com “de” sem artigo, o par fica “de... a”.","",["Não há artigo no par.","Não há artigo no par.","Correta.","“Há” é verbo.","“As” sem preposição não cabe."]],"15p540v":["“às”: com “das”, o par fica “das... às”.","",["Falta o artigo do par.","Correta.","Deve concordar no plural com “17h”.","“Há” é verbo.","Falta a preposição."]],"hf4i1u":["“a”: singular antes de plural é só preposição.","",["Não concorda com o plural.","Seria possível com artigo, mas a frase indica pessoas em geral, sem determinação.","Correta.","“Há” é verbo.","Falta a preposição pedida por “refiro-me”."]],"kie45e":["“Vestiu-se à Luís XV”: “à moda de” implícita.","",["“Cavalo” é masculino.","“Prazo” é masculino.","Correta.","“Todos” é pronome indefinido masculino.","Palavras repetidas."]],"1os3pqr":["Facultativa.","",["Não é proibida.","Não é obrigatória.","Correta.","Pode existir.","Vale no singular e no plural."]],"tgrk76":["“a”: terra como chão firme não leva artigo.","",["Não há artigo.","Correta.","“Há” é verbo.","Não há plural.","O acento agudo não existe nesse caso."]],"1nheydg":["“à”: casa especificada aceita artigo.","",["Faltou a crase.","Correta.","“Há” é verbo.","Não há plural.","O acento agudo não existe nesse caso."]]},"interpretacao":{"uaqmvk":["Se o texto diz “muitos”, o item que troca por “todos” amplia o que o autor disse. É o erro de generalização (uma forma de extrapolação). Palavras absolutas como “todos”, “sempre”, “nunca” e “somente” exigem atenção redobrada.",""],"94fvdm":["“Há quem defenda” apresenta a opinião de outras pessoas. O “contudo” marca a virada: a posição do autor costuma vir depois do conector adversativo, em oposição à ideia anterior.",""],"1a0q7wz":["A inferência é uma conclusão autorizada pelo texto, ainda que não esteja escrita. Exemplo: “Ele trancou a porta e levou a chave” permite inferir que ninguém mais entraria sem ele.",""],"2rmbdt":["O futuro do pretérito (“teria fugido”) marca hipótese ou informação ainda não confirmada. O autor relata sem se comprometer com a certeza.",""],"1wtdnrn":["“A maioria” significa mais da metade, o que autoriza dizer “muitos”. O contrário não vale: o item não poderia dizer “todos” nem “a minoria”.",""],"1mxmwb5":["A pergunta retórica não espera resposta. Ela serve para fazer o leitor pensar e reforçar a tese do autor. Exemplo: “Até quando aceitaremos tantas mortes no trânsito?”",""],"6kiqrl":["Redução é tomar uma parte do texto como se fosse o todo. Um detalhe citado de passagem raramente é o tema central.",""],"1t81q75":["Em questão de interpretação, a referência é o TEXTO, mesmo que a informação dele contrarie o que você sabe. A pergunta é sobre o que o autor disse, não sobre o que é verdade no mundo.",""],"12q81js":["O texto diz que o comércio estava “confiante de que o sol apareceria até o meio-dia”, ou seja, esperava melhora do tempo ainda pela manhã. É inferência autorizada pelo trecho.",""],"1wz6cs8":["O texto diz o oposto: o comércio “abriu as portas”. Quem suspendeu as atividades foram as escolas. É erro de contradição.",""],"684scv":["“Ainda assim” = mesmo assim, apesar disso. Apesar da neblina, dos atrasos e da suspensão das aulas, o comércio abriu. Isso é concessão.",""],"a1wyu2":["O texto fala só das “aulas da manhã”. Dizer “todo o dia” é extrapolação.",""],"cy2oq9":["O trecho final diz que a população está exposta a “pequenos crimes que raramente entram nas estatísticas”. Logo, para o autor, as estatísticas não mostram toda a criminalidade.",""],"enz6zt":["“Embora” apresenta um fato (a queda dos números) que não impede o fato principal (a insegurança persiste). É concessão, equivalente a “ainda que”.",""],"1q8hkcl":["O texto diz o contrário: os números indicam QUEDA. É erro de contradição.",""],"13f4gz8":["A oração com “porque” dá a razão de a insegurança persistir: a exposição a pequenos crimes.",""],"18w7408":["O texto diz que a sensação “persiste”, ou seja, continua. É contradição.",""],"1yd1zf8":["É a ideia central: ler é “dialogar com quem escreveu”, e quem não percebe as intenções “lê pela metade”.",""],"2bpwb8":["Os dois-pontos introduzem a explicação: depois de dizer o que ler não é, o autor explica o que é (dialogar com quem escreveu).",""],"z47p39":["O autor diz expressamente que ler “não é decifrar letras”. Decifrar é só o começo, não basta.",""],"1h0du29":["“Por isso” é conclusivo, como “portanto”: se ler é dialogar, então quem só lê palavras lê pela metade.",""],"bsw7pw":["Compreensão = o que o texto diz (“segundo o texto”). Interpretação = o que se pode concluir dele (“infere-se do texto”).",""],"xjita6":["É ir além do texto, acrescentando informações ou conclusões que o autor não deu. É o erro mais cobrado pelas bancas.",""],"qnf01i":["Exemplo: dizer que o tema de um texto sobre trânsito é “o cinto de segurança”, quando o cinto é só um dos exemplos citados.",""],"1m6mubc":["Exemplo: o texto diz que o índice “caiu” e o item afirma que “subiu”.",""],"m8c3i5":["O pressuposto está nas próprias palavras e não pode ser negado sem contradição. “Ele parou de fumar” pressupõe que fumava, qualquer que seja o contexto.",""],"188k41c":["O subentendido é uma insinuação, e o autor pode negar que quis dizê-la. Exemplo: “Está frio aqui” pode insinuar “feche a janela”.",""],"1ihog1m":["“Voltar a” pressupõe que a ação já aconteceu antes e foi interrompida.",""],"txh2bs":["“Até” sugere que não se esperava isso do diretor (que ele costuma se atrasar). É informação implícita.",""],"dg535l":["O tópico frasal é, em geral, o primeiro período do parágrafo, que apresenta a ideia que o resto vai desenvolver.",""],"4bwskf":["Exemplo: diante de uma enchente, dizer “Que dia lindo para passear!”. O contexto mostra a intenção crítica ou humorística.",""],"tit3s8":["Em “Vi o assalto do prédio”, não se sabe se o prédio foi assaltado ou se a pessoa viu o assalto estando no prédio. Em texto técnico e oficial, a ambiguidade é defeito.",""],"ij66t2":["“Sua” pode se referir ao policial ou ao suspeito. Para desfazer, use “na casa dele” ou “na casa do suspeito”.",""],"1pe43pb":["É questão de compreensão: a resposta está escrita, ainda que com outras palavras.",""],"z6thpg":["É questão de interpretação: a conclusão não está escrita, mas decorre logicamente do que está.",""],"nizr2j":["O título é um elemento que cerca o texto (paratextual) e pode antecipar o tema ou provocar o leitor.",""],"19vbxp8":["“Mesmo assim”, que também é concessiva.","",["“Portanto” é conclusão.","Correta.","“Por isso” é conclusão.","“Logo” é conclusão.","“Porque” é causa."]],"m8dmna":["Concessão.","",["Causa é o “porque”, mais adiante.","Correta.","Conclusão seria “portanto”.","Finalidade seria “para que”.","Tempo seria “quando”."]],"1wvfzm9":["A insegurança persiste apesar da queda dos números.","",["Contradição: os números indicam queda.","Extrapolação: o autor não pede abolir as estatísticas.","Correta.","Contradição: o texto fala que a população está exposta a eles.","Contradição: a insegurança persiste."]],"okhq9p":["Lê pela metade, como está escrito.","",["Contradição.","Correta.","Extrapolação: o autor diz “pela metade”, não “nada”.","Dialogar é ler por inteiro.","Quem lê só palavras não percebe as intenções."]],"ot0dom":["Ele faltava às aulas.","",["Contradição com o pressuposto.","Correta.","Não há informação sobre o futuro.","Extrapolação.","“Deixar de” sempre gera pressuposto."]],"1tcme47":["Extrapolação.","",["Redução é tomar a parte pelo todo.","Contradição é dizer o oposto.","Correta.","Inferência é conclusão autorizada, não é erro.","Paráfrase é reescrever mantendo o sentido."]],"13k73ml":["Ironia: elogio que, no contexto, significa crítica.","",["Metáfora é comparação implícita.","Correta.","Hipérbole é exagero.","Eufemismo suaviza algo desagradável.","Pleonasmo é repetição de ideia."]],"6l9pbs":["“Encontrei a mãe do menino que estava doente”: quem estava doente?","",["Sentido único.","Correta.","Sentido único.","Sentido único.","Sentido único."]],"1keldkf":["Conclusão autorizada pelo texto.","",["Informação explícita é “segundo o texto”.","Correta.","A opinião do candidato não importa.","Resumo literal é compreensão.","Significado isolado é vocabulário."]],"17cz41y":["Tópico frasal.","",["Correta.","O desenvolvimento expande a ideia.","O exemplo ilustra.","A conclusão nem sempre traz a ideia principal.","O título não faz parte do parágrafo."]],"wf8y74":["Não se esperava que ele passasse.","",["Seria o contrário.","Correta.","Extrapolação.","Extrapolação.","Contradição: ele passou."]],"1n0eny6":["Paráfrase.","",["Paródia altera com intenção crítica ou cômica.","Correta.","Citação repete as palavras originais.","Extrapolação é erro de leitura.","Contradição é dizer o oposto."]],"f8zg10":["Apesar dos transtornos causados pela neblina.","",["A neblina não é a causa, é o obstáculo.","Correta.","Não há relação de causa com as aulas.","Não há relação de causa com os ônibus.","O motivo é a confiança de que o sol apareceria."]],"4fuhr9":["Havia resistência antes de admitir.","",["“Finalmente” sugere demora.","Correta.","Ele errou.","Não há informação sobre o tamanho.","Ele admitiu."]]},"ortografia":{"6a6d4e":["O Novo Acordo Ortográfico tirou o acento dos ditongos abertos “ei” e “oi” nas paroxítonas (sílaba tônica é a penúltima): ideia, heroico, assembleia, jiboia. Nas oxítonas e monossílabos o acento continua: herói, papéis, céu.",""],"jnr6t7":["Quando o prefixo termina em vogal e a palavra seguinte começa com vogal DIFERENTE, junta-se sem hífen: auto + escola = autoescola. O hífen só aparece com vogais iguais (micro-ondas).",""],"zc3lvh":["“Infringir” = violar, desrespeitar (infringir a lei). “Infligir” = aplicar castigo (infligir uma pena). São parônimos muito cobrados.",""],"1fqbznt":["O “i” do hiato só é acentuado quando fica sozinho na sílaba (ou com “s”). Em “ju-iz”, o “i” está com o “z” na mesma sílaba e não leva acento. Em “ju-í-zes”, fica sozinho e é acentuado. O mesmo ocorre com raiz/raízes.",""],"18okby0":["Verbos derivados de “ter” e “vir” (deter, manter, conter, intervir) têm acento agudo na 3ª pessoa do singular (ele detém) e circunflexo no plural (eles detêm).",""],"1b62in1":["O verbo vem de “pesquisa”, que já tem S. Basta acrescentar -ar: pesquisa + ar = pesquisar. Só se usa -izar quando a palavra base não tem S (real → realizar).","Tem S na base? Fica S (análise → analisar). Não tem? -izar (civil → civilizar)."],"qvr70v":["Prefixo terminado em vogal + palavra começada por R ou S: junta-se e dobra-se a consoante, para manter o som: anti + social = antissocial; contra + regra = contrarregra.",""],"u9mjk5":["Reunião do júri é SESSÃO. “Seção” (ou secção) é divisão, departamento (seção eleitoral). “Cessão” é o ato de ceder.",""],"1iuko6t":["O trema foi abolido nas palavras portuguesas: linguiça, frequente, tranquilo. A pronúncia continua a mesma.",""],"1hfb3kd":["É a exceção: Müller, mülleriano, Hübner.",""],"19avqr1":["Ideia, heroico, jiboia, paranoico, estreia, assembleia.",""],"5zh74x":["Papéis, herói, anéis, céu, chapéu, dói. A mudança atingiu só as paroxítonas.",""],"ukfh61":["É paroxítona com ditongo aberto “ei”: perdeu o acento. Grafa-se “assembleia”.",""],"1eunoqx":["Leem, veem, creem, deem, voo, enjoo. Atenção: “têm” e “vêm” (plural de ter e vir) continuam com acento, porque não são “eem”.",""],"1t1f3oz":["Ele tem / eles têm. Ele vem / eles vêm. O acento serve para diferenciar singular e plural.",""],"1d50l9v":["“Pôr” (verbo) e “por” (preposição): o acento continua obrigatório.",""],"1qs9mok":["“Ontem ele pôde sair” (passado) e “Hoje ele pode sair” (presente).",""],"kx1pzo":["“Para” (verbo parar) perdeu o acento diferencial. O mesmo aconteceu com pelo, polo e pera.",""],"ta5lwm":["Toda palavra com a sílaba tônica na antepenúltima é acentuada: lâmpada, público, médico, sílaba.",""],"1t64p3h":["Caráter, tórax, hífen, útil, bíceps. Atenção: “hifens” (plural) não leva acento, porque termina em “ens”.",""],"xs6vg6":["História, água, série, régua. O ditongo crescente é semivogal + vogal (i-a, u-a).",""],"7vln7w":["Sofá, café, avô, também, parabéns.",""],"cr2myn":["“Item” é paroxítona (I-tem). Paroxítonas terminadas em “em” ou “ens” não levam acento: item, itens, jovem, jovens, nuvem.",""],"qnu357":["Saída, baú, país, saúde. O “i” ou “u” fica sozinho na sílaba (ou com “s”).",""],"3j5pt7":["Rainha, moinho, bainha.",""],"1tvrrav":["Feiura, baiuca, bocaiuva. Nas oxítonas, o acento continua: Piauí, tuiuiú.",""],"523a3x":["Micro-ondas, anti-inflamatório, contra-ataque.","Vogais iguais se separam (hífen). Vogais diferentes se juntam."],"1tndpy2":["Autoescola, infraestrutura, extraoficial, autoestima.",""],"1rmewe0":["Dobra-se a consoante: antirrábico, ultrassom, minissaia, contrarregra.",""],"15x7miz":["Anti-higiênico, super-homem, pré-história. Exceção: subumano (o “h” cai).",""],"amtjcc":["Ex-prefeito, vice-diretor, pré-vestibular, pós-graduação, pró-reitor. Quando átonos, juntam-se: prever, pospor, promover.",""],"wchmiw":["Vogais diferentes: junta-se, sem hífen. Grafa-se “autoescola”.",""],"18o798k":["“Mal” leva hífen antes de vogal, “h” ou “l”: mal-estar, mal-humorado, mal-limpo. Antes de consoante, junta-se: malcriado.",""],"1keguka":["Exceção, isenção com Ç; ascensão com S; sessão e discussão com SS. É grafia que se aprende pela leitura e pela memória.",""],"1vw3syf":["Sessão (reunião, sessão de cinema), seção (divisão, seção eleitoral), cessão (ato de ceder, cessão de direitos).",""],"15bl031":["Teste: se puder trocar por “bem”, é “mal” (dormiu mal / bem). Se puder trocar por “bom”, é “mau” (mau motorista / bom).",""],"1y31av4":["Porque = pois (resposta): “Faltei porque estava doente”. Por que = em perguntas (diretas e indiretas) ou = pelo qual: “Por que faltou?”, “O motivo por que faltou”.",""],"f409l8":["Por quê = no fim da frase, antes de ponto: “Faltou por quê?”. Porquê = substantivo, com artigo: “o porquê da decisão”.","Os quatro porquês: por que (pergunta), por quê (fim), porque (resposta), porquê (substantivo)."],"yatpmr":["“Assembleia”: paroxítona com ditongo aberto, sem acento.","",["Perdeu o acento: ideia.","Correta.","Perdeu o acento: heroico.","Perdeu o acento: voo.","Perdeu o acento: leem."]],"f1cjos":["“Herói”: oxítona com ditongo aberto.","",["Paroxítona, perdeu o acento.","Paroxítona, perdeu o acento.","Correta.","Paroxítona, perdeu o acento.","Paroxítona, perdeu o acento."]],"1yaun72":["“Autoestima”: vogais diferentes se juntam.","",["Hífen abolido nesse caso.","Correta.","Não se separa com espaço.","Não leva acento.","Não leva hífen nem acento."]],"b3c7se":["“Pôr” (verbo), para diferenciar de “por” (preposição).","",["Perdeu o acento.","Perdeu o acento.","Correta.","Perdeu o acento.","Perdeu o acento."]],"yfz378":["“Vêm / têm”: plural de vir e ter, com circunflexo.","",["Faltam os acentos do plural.","Correta.","“Vêem” e “têem” não existem.","“Veem” é do verbo ver.","“Tem” no singular não concorda com “eles”."]],"ip7ttx":["“Rainha”: hiato seguido de “nh”.","",["Leva acento (hiato).","Leva acento (hiato).","Correta.","Leva acento (hiato).","Leva acento (hiato)."]],"1r741mh":["“Exceção”.","",["Correta.","Grafia errada.","Grafia errada.","Grafia errada.","Grafia errada."]],"1jihld3":["“Por que”: pergunta indireta (por qual motivo).","",["“Porque” é resposta.","Correta.","“Porquê” é substantivo.","“Por quê” é só no fim da frase.","Não existe."]],"2h2q49":["“Caráter”: paroxítona terminada em “r”.","",["Paroxítona em “em” não leva acento.","Paroxítona em “ens” não leva acento.","Correta.","Paroxítona em “ens” não leva acento.","Paroxítona em “ens” não leva acento."]],"9spkk5":["“Ex-presidente”: “ex” com sentido de anterior leva hífen.","",["Correta.","Falta o hífen.","Não se separa com espaço.","Não leva acento.","Não se usa ponto."]]},"pontuacao":{"xotg5e":["Por mais longo que seja, o sujeito não se separa do verbo por vírgula. O certo é “Os condutores flagrados em excesso de velocidade durante o feriado foram autuados”. Vírgula só caberia se houvesse uma intercalação, com vírgula de abertura e de fechamento.","Regra de ouro: não se separa sujeito de verbo, nem verbo de complemento, com uma vírgula só."],"10if8cc":["Em regra não se usa vírgula antes de “e”. Mas, quando as orações têm sujeitos diferentes (o agente / o condutor), a vírgula é aceita e ajuda a leitura.",""],"1lb6y0g":["Adjunto adverbial curto (uma ou duas palavras) deslocado para o início admite ou não vírgula: “Ontem, a PRF...” ou “Ontem a PRF...”. Se for longo, a vírgula é recomendada.",""],"128dvec":["“Condutor” é vocativo (chamamento), e o vocativo sempre vem isolado por vírgula: “Condutor, desligue o motor”.",""],"e3llso":["A vírgula marca a omissão do verbo “preferiam” (outros preferiam a terra). Essa omissão de termo já dito se chama zeugma.",""],"17wqoti":["Vírgulas, travessões e parênteses podem isolar a mesma explicação sem mudar o sentido. O que muda o sentido é RETIRAR a pontuação, porque a oração passa a ser restritiva.",""],"8hs4kx":["Conjunção deslocada para o meio da oração vem entre vírgulas: “O agente, porém, não autuou”. Se estivesse no início, seria “Porém o agente não autuou” ou “Porém, o agente...”.",""],"6fufw2":["O ponto e vírgula é justamente usado para separar orações coordenadas longas, que já têm vírgulas, ou com conjunção deslocada: “Ele estudou muito; não conseguiu, porém, a vaga”.",""],"16zgaar":["Exemplo errado: “O prefeito, assinou o decreto”. Certo: “O prefeito assinou o decreto”.",""],"mdxmba":["Exemplo errado: “O prefeito assinou, o decreto”. Certo: “O prefeito assinou o decreto”.",""],"xhfg7w":["A vírgula separa o sujeito (“Os candidatos aprovados”) do verbo (“tomarão”). É erro.",""],"xg5al7":["Vocativo é o chamamento do interlocutor: “Pedro, venha cá”, “Venha cá, Pedro”, “Venha, Pedro, cá”.",""],"ecnaax":["O aposto explica um termo anterior: “Brasília, a capital do país, é planejada”.",""],"36cn8x":["Exemplo: “Na manhã de ontem, o juiz decidiu”. Na ordem direta (no fim da oração), não precisa de vírgula: “O juiz decidiu na manhã de ontem”.",""],"su15re":["Exemplo: “Ontem choveu” ou “Ontem, choveu”.",""],"tkjb08":["A explicativa vale para todo o grupo: “Os servidores, que faltaram, foram advertidos” (todos faltaram e todos foram advertidos).",""],"1pz1k72":["A restritiva limita o grupo: “Os servidores que faltaram foram advertidos” (só os que faltaram).","Com vírgula = todos. Sem vírgula = só alguns."],"ojxgm0":["Exemplo: “Comprou pão, leite e café”. O último item, ligado por “e”, não leva vírgula.",""],"ku51hi":["Exemplo: “Estudou, mas não passou”. Vale para mas, porém, contudo, todavia, entretanto.",""],"1rsav1z":["Exemplo: “Ele saiu, e a mãe ficou”. Também se usa quando o “e” tem valor adversativo (= mas): “Estudou muito, e não passou”.",""],"plu97o":["Exemplo: “Eu prefiro café; ela, chá” (ela prefere chá).",""],"1fkpjlk":["Exemplo: “O condutor, isto é, o motorista, foi autuado”.",""],"7wpu67":["Exemplo: “Ele, porém, não veio”, “Não veio, portanto, à reunião”.",""],"1jgxte9":["Serve como pausa maior que a vírgula e menor que o ponto, organizando períodos longos.",""],"x442l":["É o padrão dos incisos de leis: “I – ...; II – ...; III – ...”.",""],"16qfto4":["Exemplos: “Trouxe tudo: livros e cadernos” (enumeração); “O motivo era um só: medo” (explicação); “Disse: ‘Volto logo’” (citação).",""],"w4yg5e":["Exemplos: citação textual, palavra usada em sentido irônico (“Que ‘ótimo’ serviço”), termo estrangeiro.",""],"1tl4aor":["Exemplo: “O condutor — que estava sem cinto — foi multado”. Dão mais destaque que as vírgulas.",""],"o22e7v":["Exemplo: “O CTB (Lei 9.503/1997) trata das infrações”. Trazem informação secundária.",""],"1nmq0ie":["Exemplo: “Eu ia dizer que... deixa pra lá”.",""],"14lv2t0":["“Não, espere” (eu digo não e peço que espere). “Não espere” (não fique esperando). O sentido é oposto.",""],"1dqe7v2":["A vírgula separa o sujeito “O diretor” do verbo “disse”. É erro.",""],"138ujrb":["“Minha irmã” explica quem é Maria (aposto explicativo) e vem entre vírgulas.",""],"1p3pnrp":["Sem as vírgulas, o aposto fica solto e a frase fica mal construída.",""],"1mujq2j":["É o padrão em documentos e na redação oficial: “Belo Vale, 4 de novembro de 2026.”",""],"1897ttx":["O Manual de Redação da Presidência usa vírgula depois do vocativo: “Senhor Prefeito,”, “Excelentíssimo Senhor Presidente da República,”.",""],"gvr28x":["Direta: “Você vem?”. Indireta (a pergunta é contada, dentro de outra frase): “Perguntou se você viria.”",""],"bz99ep":["Exemplo: “Saindo de casa, vi o acidente”. A oração reduzida no início funciona como adjunto adverbial deslocado.",""],"1d2wl2p":["“Estudou muito, mas não passou”: vírgula antes da adversativa.","",["A vírgula está depois do “mas”.","Correta.","A vírgula separa o verbo do advérbio.","A vírgula separa o “não” do verbo.","Vírgula no final da frase."]],"2a5v99":["O vocativo.","",["Sujeito não se separa do verbo.","Objeto não se separa do verbo.","Correta.","O núcleo do predicado não vem isolado.","O complemento nominal não vem isolado."]],"1ttu8ri":["Só os que faltaram foram advertidos (oração restritiva).","",["Sem vírgula, só alguns faltaram.","Correta.","Alguns faltaram.","Só os que faltaram.","A frase está correta."]],"hj5p7q":["Todos os servidores faltaram (oração explicativa).","",["Com vírgula, a oração vale para todos.","Correta.","Foram advertidos.","A frase está correta.","Não há referência a presentes."]],"a8s0bp":["Ponto e vírgula.","",["O ponto final só no último inciso.","Correta.","O travessão separa o número do texto do inciso.","Não se usa exclamação.","Não se usam reticências."]],"5sqyl":["Omissão do verbo (zeugma).","",["Não há chamamento.","Correta.","Não há explicação de termo.","Não é lista de itens.","Não há adjunto deslocado."]],"11r47rx":["Enumeração.","",["Não há citação.","Correta.","Não há vocativo.","Não há ironia.","Não há pergunta."]],"1kcena3":["Ponto final.","",["Interrogação é para pergunta direta.","Correta.","Reticências indicam interrupção.","Dois-pontos introduzem algo.","Exclamação indica emoção."]],"6vj4kw":["A conjunção deslocada.","",["O sujeito é “ele”, que não está isolado.","Correta.","Não há vocativo.","Não há objeto isolado.","Não há aposto."]],"18waeye":["O lugar da data.","",["Não há verbo.","Correta.","Dia e mês se ligam por “de”.","Mês e ano se ligam por “de”.","Separa o lugar da data."]],"eiad46":["“Não, quero café” (quero) × “Não quero café” (não quero).","",["Correta.","A segunda está errada (separa sujeito e verbo).","Vírgula final não muda sentido, só está errada.","A vírgula está errada.","Há uma alternativa correta."]]},"redacao-oficial":{"vo1utx":["O Manual tem só dois fechos: “Respeitosamente” para autoridades de hierarquia superior (inclusive o Presidente da República) e “Atenciosamente” para autoridades de mesma hierarquia ou inferior e para particulares.",""],"6iz5wc":["Apesar do “Vossa”, os pronomes de tratamento levam verbo e possessivo na 3ª pessoa: “Vossa Excelência e sua equipe estão convidados”.","Fala-se COM a pessoa (Vossa), mas a concordância é de 3ª pessoa (sua, está). Fala-se SOBRE a pessoa: Sua Excelência."],"11u1jds":["A 3ª edição (2018) unificou aviso, ofício e memorando no chamado padrão ofício, com a denominação única “ofício”.",""],"ejl7mp":["“Excelentíssimo Senhor” é reservado aos chefes de Poder: Presidente da República, Presidente do Congresso Nacional e Presidente do STF. Para as outras autoridades, o vocativo é “Senhor” + cargo (“Senhor Senador,”).",""],"1xs9mhr":["Texto conciso não tem palavras inúteis, repetições ou rodeios, mas também não corta informação importante.",""],"lx954s":["O Manual aboliu “Ilustríssimo” e “Digníssimo”. Para particulares e autoridades tratadas por Vossa Senhoria, basta “Senhor” ou “Senhora”.",""],"eep7gw":["Exemplo: “Belo Vale, 3 de novembro de 2026.” O mês vai por extenso e com inicial minúscula.",""],"3cz274":["Para reitor, o tratamento é “Vossa Magnificência”, com o vocativo “Magnífico Reitor,”.",""],"76amtp":["É a definição do Manual de Redação da Presidência da República (3ª edição).",""],"xk1nsh":["A 3ª edição lista: clareza, precisão, objetividade, concisão, coesão, coerência, impessoalidade, formalidade, padronização e uso da norma-padrão.",""],"nrfoin":["Quem fala é o órgão, e não o servidor como pessoa. Por isso não há impressões pessoais, e o destinatário é tratado como cidadão ou outro órgão, sem intimidade.",""],"ftur6z":["É um dos atributos da redação oficial.",""],"1rv9c4r":["O texto claro não exige esforço para ser entendido. Para isso, usa ordem direta, palavras comuns e frases curtas.",""],"1qc8z22":["A redação oficial exige formalidade e norma-padrão em qualquer caso, independentemente de quem é o destinatário.",""],"1bxu8ir":["“Vossa Excelência decidiu”, e não “decidistes”.",""],"1ifxij":["“Vossa Senhoria e sua equipe”, e não “vossa equipe”.",""],"1tmdp55":["Para homem: “Vossa Excelência está cansado”. Para mulher: “Vossa Excelência está cansada”.",""],"1r1lw8b":["Vossa Excelência vale para as altas autoridades dos três Poderes: Presidente e Vice, ministros, parlamentares, juízes, membros de tribunais, governadores, prefeitos, entre outros.",""],"15zglz7":["Exemplo: “Excelentíssimo Senhor Presidente da República,”.",""],"nlpkhl":["Exemplos: “Senhor Senador,”, “Senhor Ministro,”, “Senhor Prefeito,”.",""],"jo5z4u":["É o tratamento tradicional dos reitores.",""],"1ov7lmt":["O Manual considera que a dignidade é pressuposto de qualquer cargo público, e por isso não precisa ser dita.",""],"1onqnsa":["Deve ser usado só para quem tem doutorado. Em comunicações oficiais, “Senhor” basta.",""],"1ry56am":["Todos seguem o padrão ofício e se chamam “ofício”.",""],"1d4bvh5":["Inclusive o Presidente da República.",""],"ewnpiz":["Também para autoridades de hierarquia inferior e particulares.",""],"1jc85p0":["O Presidente é autoridade superior a todos: o fecho é “Respeitosamente”.",""],"h9masu":["Exemplo: “OFÍCIO Nº 12/2026/SEC”. O tipo vai em maiúsculas.",""],"jonat2":["Exemplo: “Belo Vale, 4 de novembro de 2026.”",""],"8sfw0l":["Deve ser curto e indicar o tema, para facilitar o arquivo e a busca.",""],"prnm7a":["É a regra do Manual (3ª edição) para a organização do texto no padrão ofício.",""],"1n5r8ga":["Para as demais autoridades, a assinatura vem acompanhada do nome e do cargo.",""],"1d3yjmd":["O e-mail tem valor documental quando há como confirmar a autoria e o recebimento (por exemplo, por certificado digital ou sistema próprio).",""],"1k5z6qz":["Serve para informar o Presidente ou propor medidas, como um projeto de lei ou decreto.",""],"1mn9m8m":["Exemplos: enviar projeto de lei, comunicar veto, apresentar o plano de governo na abertura dos trabalhos.",""],"69um69":["O decreto define “senhor” (ou “senhora”) como o tratamento usual entre agentes públicos federais e proíbe tratamentos como Vossa Excelência, doutor e digníssimo nessas comunicações. Ele não alcança os outros Poderes nem os Estados e Municípios.",""],"13w8grj":["Exemplo: “Senhor Prefeito,”.",""],"mnlgdz":["O verbo fica na 3ª pessoa: “Vossa Excelência está convidado”.",""],"84tilf":["“Respeitosamente”.","",["É para mesma hierarquia, inferior ou particular.","Correta.","Não está no Manual.","Não está no Manual.","Informal demais."]],"10rmyh2":["“Vossa Magnificência”.","",["É para altas autoridades.","É para as demais autoridades e particulares.","Correta.","É para cardeais.","É para religiosos."]],"g28xrq":["“Senhor Senador,”.","",["“Excelentíssimo” é só para chefes de Poder.","Correta.","Foi abolido.","Foi abolido.","Informal demais."]],"f56mnj":["“Vossa Excelência está satisfeito”: 3ª pessoa.","",["“Estais” é 2ª pessoa do plural.","Correta.","“Estás” é 2ª pessoa do singular.","“Estão” é plural.","“Estou” é 1ª pessoa."]],"fs1hue":["Ofício, aviso e memorando.","",["Correta.","A mensagem tem forma própria.","São atos normativos.","Não são comunicações do padrão ofício.","Não foram unificados."]],"1qpp1e1":["“4 de novembro de 2026”.","",["Zero à esquerda e mês com maiúscula.","Correta.","O mês deve ir por extenso.","O dia vai em número e o mês com minúscula.","Mês com maiúscula e ponto no ano."]],"1mfk3i3":["O uso de jargões e gírias.","",["É atributo.","É atributo.","É atributo.","É atributo.","Correta."]],"foqwt1":["Mensagem.","",["A exposição de motivos vai do ministro ao Presidente.","Correta.","O ofício é comunicação entre órgãos.","Portaria é ato normativo.","O aviso foi unificado ao ofício."]],"1ne6y5n":["Ao Presidente da República, por ministro.","",["Ao Congresso vai a mensagem.","Correta.","Não é para particulares.","Não é para o STF.","Não é para prefeitos."]],"1ikw46l":["“Digníssimo”.","",["Continua em uso.","Continua em uso.","Correta.","Continua em uso.","Continua em uso."]],"17uwe53":["“Atenciosamente”.","",["É para autoridade superior.","Correta.","Não está no Manual.","Não está no Manual.","Não existe."]],"1dedpg0":["“Sua”: 3ª pessoa.","",["“Vossa” não é usado como possessivo aqui.","Correta.","“Tua” é 2ª pessoa.","“Nossa” muda o sentido.","“Vosso” é 2ª pessoa e masculino."]]},"reescrita":{"w597ng":["Na passiva, o objeto direto (“os condutores”) vira sujeito, o sujeito (“o agente”) vira agente da passiva, e o verbo vira “ser” + particípio, no MESMO tempo do original: autuava (imperfeito) → eram autuados (imperfeito).",""],"1bn41dh":["No discurso indireto, a fala é contada por outra pessoa, e os tempos e referências mudam: “eu” vira “ele”, “vou pagar” vira “iria pagar” e “amanhã” vira “no dia seguinte”. Fica: “Ele disse que iria pagar a multa no dia seguinte”.","Discurso indireto: presente → imperfeito; futuro → futuro do pretérito; hoje → naquele dia; amanhã → no dia seguinte; aqui → ali."],"2pnao4":["Hiperônimo é a palavra de sentido mais geral (veículo), que inclui a mais específica (caminhão, o hipônimo). Usar o termo geral para retomar o específico é recurso de coesão.",""],"14duwav":["A posição do “só” muda o sentido. “Só o agente viu” = ninguém mais viu. “O agente só viu” = ele apenas viu, não fez mais nada (ou viu só o acidente e nada mais).",""],"5g9u88":["“Ao terminar” é oração reduzida de infinitivo com valor de tempo. Desenvolvida, fica “Quando terminou a vistoria”. A reescrita mantém o sentido.",""],"1q0winn":["É prosopopeia (personificação): atribui ação humana (dormir) a um ser que não é humano (a cidade). Hipérbole é exagero.",""],"jjpit2":["Eufemismo é suavizar uma ideia desagradável. “Faltou com a verdade” diz que ele mentiu de forma mais leve.",""],"ec8fk5":["“Deve” indica obrigação; “pode” indica possibilidade ou permissão. A troca muda o sentido, e as bancas cobram muito essa diferença.",""],"14jw11a":["Exemplos: belo e bonito, carro e automóvel. Nem todo sinônimo serve em qualquer contexto.",""],"ou73gv":["Exemplos: alto e baixo, deferir e indeferir.",""],"bv3shi":["“Cela” (cômodo de prisão) e “sela” (arreio do cavalo) têm a mesma pronúncia e grafias diferentes (homônimos homófonos). Também há homônimos com mesma grafia e som (“manga” fruta e “manga” da camisa).",""],"q4xha6":["São parecidas, mas não iguais: eminente/iminente, ratificar/retificar, tráfego/tráfico.",""],"1vniw8w":["“O eminente juiz” (ilustre). “O perigo iminente” (prestes a acontecer).","Iminente = Instante (vai acontecer já)."],"1f0krfj":["“Ratifico o que disse” (confirmo). “Retifico o erro” (corrijo, deixo reto).",""],"8xi46b":["“Descriminar” = tirar o caráter de crime. “Discriminar” = distinguir ou tratar alguém de forma desigual.",""],"1yqsy6x":["“O pedido foi deferido” (concedido). “A decisão foi diferida” (adiada). “As opiniões diferem” (são diferentes).",""],"1qw8uya":["“O juiz infligiu a pena” (aplicou). “O condutor infringiu a lei” (violou).",""],"w0lbyr":["“Mandado de prisão”, “mandado de segurança”. “Mandato do prefeito”, “mandato do advogado”.",""],"15ddhl5":["“O comprimento da pista” (medida). “O cumprimento da ordem” (execução), “um cumprimento” (saudação).",""],"1h7di37":["“O tráfego na BR está intenso”. “Tráfico de drogas”.",""],"gv99qk":["“A pedra caiu” (denotação). “Coração de pedra” (conotação: insensível).",""],"z7ye5z":["“Pedra” indica insensibilidade, não o material. É metáfora.",""],"18xvb5b":["“Banco” pode ser assento, instituição financeira ou banco de dados. O contexto define o sentido.",""],"d19h1t":["“Assinou” (perfeito) → “foi assinada” (perfeito). Se o tempo mudar, a reescrita está errada.",""],"100ktg6":["“Assinará” é futuro do presente. Na passiva: “A sentença será assinada pelo juiz”. “Foi assinada” está no passado.",""],"1qlk186":["As duas são adversativas. A pontuação pode mudar: “Estudou; no entanto, não passou”.",""],"n39e6o":["“Visto que”, “já que” e “uma vez que” são causais, como “porque”.",""],"2qpiao":["“Embora” é concessivo; “portanto” é conclusivo. A troca muda a lógica e a estrutura.",""],"1dv8gox":["Mesma ideia (concessão), estruturas diferentes: “Embora chovesse” (subjuntivo) = “Apesar de chover” (infinitivo) = “Apesar da chuva” (substantivo).",""],"g81qr8":["As duas expressões são concessivas, e o verbo foi ajustado corretamente (subjuntivo → infinitivo).",""],"6203qv":["São os dois critérios das questões de reescrita: o novo trecho precisa dizer a mesma coisa E estar gramaticalmente correto.",""],"yiowd5":["Por isso só verbos transitivos diretos admitem voz passiva: precisa haver objeto direto para virar sujeito.",""],"1ec8o3g":["Sem objeto direto, não há o que virar sujeito. Exceções tradicionais: “obedecer”, “desobedecer” e “responder”, que admitem passiva (“A ordem foi obedecida”).",""],"1cxtc9m":["Exemplos: subir para cima, entrar para dentro, elo de ligação. O pleonasmo de reforço, usado com intenção estilística (“Vi com meus próprios olhos”), não é vício.",""],"1n7zj1l":["Exemplos: “ele partiu” (morreu), “pessoa de idade” (velho).",""],"141cu9l":["Exemplos: “chorei rios de lágrimas”, “já disse mil vezes”.",""],"ik3jif":["Autor pela obra (ler Machado), lugar pela instituição (o Planalto decidiu), parte pelo todo (não há teto para ele).",""],"ij3gzz":["É uma metáfora já cristalizada: pé da mesa, asa da xícara, braço da cadeira, céu da boca.",""],"1lwa0t7":["“Iminente”.","",["“Eminente” é ilustre.","Correta.","Não existe.","“Imanente” é o que é inerente, próprio de algo.","“Emitente” é quem emite (um cheque, por exemplo)."]],"19351bg":["“Mandado”: ordem judicial.","",["“Mandato” é delegação de poderes.","Correta.","“Mandamento” é preceito, regra.","“Mandante” é quem manda.","Forma verbal, não cabe."]],"axdc44":["“Retificar”.","",["“Ratificar” é confirmar.","Correta.","“Reificar” é tratar como coisa.","“Ratear” é dividir proporcionalmente.","“Rectificar” é grafia antiga."]],"dca9ak":["“Infringiu”.","",["“Infligiu” é aplicou pena.","Correta.","“Inferiu” é concluiu.","“Afligiu” é angustiou.","Forma pronominal não cabe."]],"1u9cy9l":["“Tráfego”: fluxo.","",["“Tráfico” é comércio ilegal.","Correta.","“Trafico” é verbo (eu trafico).","Não existe.","Não existe."]],"5f3p7c":["“O projeto será aprovado pela comissão”: futuro do presente.","",["Está no passado.","Correta.","Está no imperfeito.","Está no presente.","Está no futuro do pretérito."]],"7911tl":["“Apesar de chover, saímos”: concessão.","",["“Como” aqui é causal.","Correta.","“Porque” é causal.","Vira condição e hipótese.","“Portanto” é conclusão."]],"nronzr":["Metonímia: o lugar (Palácio do Planalto) pela instituição (Presidência).","",["Não há comparação.","Correta.","Não há exagero.","Não há suavização.","Não é falta de termo próprio."]],"1n4m4pg":["Catacrese: metáfora cristalizada por falta de termo próprio.","",["Não é inovadora: já está fixada na língua.","Correta.","Não há ironia.","Não há repetição.","Não há oposição."]],"plpidb":["“Entrou para dentro da sala”: quem entra, entra para dentro.","",["Sem redundância.","Correta.","Sem redundância.","Sem redundância.","Sem redundância."]],"qokxi4":["“Deferido”.","",["“Diferido” é adiado.","Correta.","“Diferenciado” é distinto.","“Deferente” é respeitoso.","“Defendido” é protegido."]],"1wqy3qh":["“O preço do pão subiu”: sentido literal (o valor aumentou).","",["“Mãos de fada” é figurado (habilidade).","Correta.","“Raposa” é figurado (esperteza).","“A mil” é exagero figurado.","“Coração de ouro” é figurado (bondade)."]]},"regencia":{"h79jm0":["“Aspirar” com sentido de desejar pede a preposição “a” (aspira A algo). Com pronome relativo, a preposição vem antes dele: “o cargo a que aspira”.",""],"2m4ghl":["“Preferir” já significa “querer mais”. Por isso não aceita “mais”, “antes” nem “do que”. A regência é “preferir uma coisa A outra”: “Prefiro estudar a sair”.",""],"muwd9y":["“Proceder” com sentido de realizar, dar início, pede a preposição “a” (proceder A algo). “Vistoria” é feminina e aceita artigo: a + a = à.",""],"xepj9":["Quem participa, participa DE algo. A preposição tem que aparecer antes do relativo: “A operação de que participei” ou “da qual participei”.",""],"48pr45":["“Assistir” = ajudar, prestar assistência é transitivo direto: “assistiu o ferido”. Já “assistir” = ver pede “a”: “assistiu ao jogo”.","Assistir: ver = A (assisti ao filme); ajudar = direto (assisti o doente); caber = A (assiste ao réu o direito); morar = EM (arcaico)."],"3ci4z7":["Verbos de lugar como residir, morar, situar-se pedem a preposição “em”: “Ele reside na Rua das Flores”. O mesmo vale para “estabelecido na rua”, “situado na avenida”.",""],"1x86vi9":["Com pronome (esquecer-se, lembrar-se), o verbo pede “de”: “Esqueci-me do documento”. Sem pronome, é direto: “Esqueci o documento”.",""],"1ehitj4":["“Simpatizar” não é pronominal. O certo é “Simpatizo com a proposta”. O mesmo vale para “antipatizar”.",""],"17csxzt":["Exemplo: “Assisti ao jogo”, “Assisti à palestra”. Por ser indireto, não admite voz passiva na norma tradicional: “O jogo foi assistido” é condenado.",""],"1n8of0z":["Exemplo: “O médico assistiu o paciente”.",""],"7w0cwc":["Exemplo: “Assiste ao réu o direito de defesa” (cabe ao réu).",""],"1kemjwe":["No sentido de ver, “assistir” pede “a”: “Assisti ao filme”.",""],"sbsee1":["Exemplo: “Aspira ao cargo de agente”.",""],"1prhxeg":["Exemplo: “Aspirou o ar puro”, “aspirou o pó”.",""],"44kjpf":["Exemplo: “O projeto visa ao bem comum”. Muitos gramáticos modernos já aceitam também a forma direta (“visa o bem comum”), mas a regência tradicional, cobrada pelas bancas, é com “a”.",""],"znekg3":["Exemplo: “O gerente visou o cheque”. Também é direto com sentido de mirar: “visou o alvo”.",""],"16noqjg":["Exemplo: “Obedeça às leis”, “Obedeça aos sinais”. O mesmo vale para “desobedecer”.",""],"1uknc5u":["Exemplo: “Prefiro café a chá”.",""],"hfm8x9":["Sem “mais” e sem “do que”: “Prefiro estudar a trabalhar”.",""],"nuk5nc":["Exemplo: “A decisão implica custos”. Com sentido de antipatizar, pede “com”: “Ele implica com tudo”.",""],"t9smia":["Na norma tradicional, “implicar” (acarretar) é direto: “A decisão implica custos”. A forma com “em” é muito usada, mas ainda é condenada pelas bancas.",""],"1957nbw":["Verbos de movimento (chegar, ir, voltar) pedem “a”: “Cheguei ao trabalho”. “Cheguei em casa” é aceito na fala, mas a norma pede “cheguei a casa”.",""],"1rsnsmw":["“Fui à escola” (ida passageira) ou “Fui para a escola” (ideia de permanência ou destino).",""],"17ue2xk":["Sem pronome: direto (“Esqueci o livro”). Com pronome: “de” (“Esqueci-me do livro”). Erro comum: “Esqueci do livro” (sem pronome e com preposição).",""],"m3forv":["“Lembrei o fato” ou “Lembrei-me do fato”.",""],"11xrops":["Exemplo: “Paguei a conta ao banco”, “Paguei ao pedreiro”. A coisa paga é objeto direto; a pessoa, indireto.",""],"1rf4fke":["Exemplo: “Perdoou a dívida ao amigo”, “Perdoou ao amigo”. Mesma regra de “pagar”.",""],"6me36k":["Exemplo: “Informei o prazo ao candidato” ou “Informei o candidato do prazo”. O que não pode é usar duas preposições ou dois objetos diretos.",""],"19o5e04":["Na norma-padrão: “Ela namora o vizinho”. “Namorar com” é uso coloquial.",""],"8qnu12":["“Quero muito a meus filhos” (estimo). No sentido de desejar, é direto: “Quero um carro”.",""],"q2lkvo":["O sujeito é o que é difícil, e a pessoa é objeto indireto: “Custou-me aceitar” (aceitar custou a mim). A forma “Eu custei a aceitar” é condenada pela norma tradicional.",""],"105cse2":["Exemplo: “O perito procedeu ao exame”. No sentido de vir de, pede “de”: “O voo procede de Lisboa”.",""],"m3lydx":["Exemplo: “Respondeu ao ofício”, “Responda às perguntas”. O conteúdo da resposta é objeto direto: “Respondeu que sim”.",""],"1xn7lmv":["Substantivos, adjetivos e advérbios também pedem preposições: apto para, favorável a, residente em, ansioso por.",""],"1ldtv41":["Os nomes derivados costumam ter a mesma regência dos verbos: obedecer a → obediência a.",""],"1xzrc06":["A preposição do verbo passa para a frente do relativo: assistir A → “o filme a que assisti”; gostar DE → “o livro de que gosto”.",""],"apl3es":["“Aspirar” (desejar) pede “a”: “O cargo a que aspiro”.",""],"1fg3sp0":["“Tratar de” pede “de”, que vai para antes do relativo: “de que trata”.",""],"kqx30o":["“Paguei ao pedreiro o serviço”: pagar algo a alguém.","",["A pessoa é objeto indireto.","Correta.","Inverte os papéis.","“Com” não é a preposição.","“De” não é a preposição."]],"1e20bhn":["“A que”: referir-se A.","",["Falta a preposição.","Correta.","“Referir-se” não pede “de”.","Não pede “em”.","Não pede “com”."]],"1mhe1n0":["“A que”: obedecer A.","",["Falta a preposição.","Correta.","Obedecer não pede “de”.","Obedecer não pede “em”.","Obedecer não pede “por”."]],"178mzwk":["A preposição “a”.","",["Objeto direto é no sentido de pôr visto ou mirar.","Correta.","Não pede “em”.","Não pede “de”.","Tem complemento."]],"1ha6v42":["“À”: favorável A + a proposta.","",["Não pede “de”.","Correta.","Não pede “em”.","Não pede “por”.","Não pede “com”."]]},"sintaxe":{"jxhgx":["Entre vírgulas, a oração adjetiva é explicativa: a característica vale para TODO o grupo. Logo, todos os motoristas estavam sem cinto e todos foram autuados. Sem vírgulas, seria restritiva: só os que estavam sem cinto foram autuados.",""],"11tvtuc":["“Haver” no sentido de existir é impessoal: a oração não tem sujeito. “Muitos acidentes” é objeto direto. Por isso o verbo fica no singular (“houve”, e não “houveram”).",""],"uvnqnj":["As rodovias SOFREM a fiscalização (são fiscalizadas): valor paciente = complemento nominal. Se o termo PRATICASSE a ação (“a fiscalização da PRF”, a PRF fiscaliza), seria adjunto adnominal.","Termo com preposição ligado a substantivo abstrato: sofre a ação = complemento nominal; pratica ou possui = adjunto adnominal."],"1qoy3j8":["Verbo na 3ª pessoa do plural, sem nenhuma referência anterior a quem roubou, indica sujeito INDETERMINADO: não se sabe ou não se quer dizer quem praticou a ação. Oculto seria se o sujeito pudesse ser identificado pela terminação ou pelo contexto.",""],"r1b03j":["Há dois núcleos: uma ação (“saiu”, verbo significativo) e um estado do sujeito (“nervoso”, predicativo). Equivale a “O condutor saiu e estava nervoso”.",""],"7qvziu":["Sem as vírgulas, a oração continua correta, mas passa a ser restritiva. O que muda é o SENTIDO (de “todos” para “só alguns”), não a correção gramatical.",""],"b44zmb":["O que é necessário? Que todos usem cinto. A oração funciona como sujeito de “é necessário”: oração subordinada substantiva subjetiva. Teste: troque por “isso” (Isso é necessário).",""],"17ipy87":["“Senhor” é vocativo: serve para chamar o interlocutor, isolado por vírgula, e não faz parte do sujeito nem do predicado. O sujeito de “encoste” é “você”, oculto.",""],"kpzktv":["São os termos essenciais da oração. Exemplo: “O agente (sujeito) / multou o condutor (predicado)”.",""],"142j44d":["Simples: “O agente chegou”. Composto: “O agente e o perito chegaram”.",""],"1ldvy0i":["Em “Estudamos muito”, a terminação “-mos” mostra que o sujeito é “nós”.",""],"35dbx4":["“Roubaram meu carro”: não se sabe quem roubou. Se houvesse referente anterior (“Os ladrões fugiram. Roubaram meu carro”), seria sujeito oculto.",""],"b2fqg9":["“Precisa-se de ajudantes” (VTI + se), “Vive-se bem aqui” (intransitivo + se). O verbo fica sempre no singular.",""],"nnokk2":["Chover, ventar, nevar, trovejar, anoitecer: não há quem pratique a ação. Em sentido figurado têm sujeito: “Choveram críticas”.",""],"1qq56by":["“Havia muitos alunos”, “Houve acidentes”. A oração é sem sujeito, e o termo seguinte é objeto direto.",""],"10ovty6":["“Haver” = existir fica no singular: “Havia muitas pessoas na sala”.",""],"2io2i2":["“Faz dois anos”, “Fazia meses”. A oração não tem sujeito, e o verbo fica no singular.",""],"1v5ikpt":["Exemplo: “O agente multou o condutor”. Há casos de objeto direto preposicionado, com preposição não exigida pelo verbo (“Amar a Deus”).",""],"190bc07":["Exemplo: “Ele obedeceu às regras” (obedecer A). A preposição é exigida pelo verbo.",""],"bgsy1n":["Exemplos: “confiança em Deus”, “favorável à proposta”, “longe de casa”. Sempre com preposição.",""],"1tp853c":["Adnominal: “o carro novo”, “a casa de madeira”. Adverbial: “chegou cedo”, “saiu de carro”.",""],"1old0u3":["Exemplo: “Pedro, o diretor, saiu”. Há também aposto especificador, sem vírgulas: “o rio Amazonas”, “a cidade de Belo Vale”.",""],"xovq55":["Fica fora da estrutura sujeito + predicado. Exemplo: “Maria, venha cá”.",""],"qm2r5r":["Exemplo: “A lei foi aprovada pelo Congresso”. Na ativa, o agente vira sujeito: “O Congresso aprovou a lei”.",""],"1go25hz":["Verbal: “O agente multou o condutor” (núcleo: multou). Nominal: “O agente está cansado” (núcleo: cansado, com verbo de ligação).",""],"1irrkyq":["Exemplo: “Ele chegou cansado” (ação: chegou; estado: cansado).",""],"9xrj34":["Uma não exerce função sintática na outra. Exemplo: “Estudou e passou”.",""],"1ajipb8":["Funcionam como sujeito, objeto, adjunto adnominal, adjunto adverbial etc. da oração principal.",""],"1ef7prv":["Pode ser subjetiva, objetiva direta ou indireta, completiva nominal, predicativa ou apositiva. Em geral é introduzida pela conjunção integrante “que” ou “se”.",""],"1rlsfxw":["Ela limita o grupo: só os alunos que estudaram passaram.",""],"q850m2":["Ela vale para o grupo todo: os alunos (todos) estudaram e passaram.",""],"13iezxx":["Sem vírgulas, a oração é restritiva.",""],"u2fk0t":["Com vírgulas, a oração é explicativa.",""],"3co9nl":["Tipos: causal, consecutiva, condicional, concessiva, conformativa, comparativa, final, proporcional e temporal.",""],"10am12v":["“Pois” antes do verbo é explicativo (= porque, dá a razão de algo). Depois do verbo, entre vírgulas, é conclusivo.",""],"1j43abl":["“Pois” depois do verbo e entre vírgulas é conclusivo (= portanto).",""],"13gowou":["Ela funciona como sujeito de “é preciso” (isso é preciso): é substantiva subjetiva. A adjetiva se refere a um substantivo anterior e é introduzida por pronome relativo.",""],"oae42l":["Exemplo: “Alugam-se salas” = “Salas são alugadas”. O verbo concorda com o sujeito paciente.",""],"op0v8e":["Inexistente: fenômeno da natureza.","",["Não há quem praticou a ação.","Indeterminado existe, mas não é identificado.","Correta.","Não há núcleo de sujeito.","Não há núcleos de sujeito."]],"kqx30o":["“Havia muitos candidatos”: haver impessoal.","",["“Haviam” no plural é erro.","Correta.","“Houveram” no plural é erro.","“Haverão” no plural é erro.","“Hão” no plural é erro."]],"z6cm8v":["Índice de indeterminação do sujeito: VTI + se.","",["A apassivadora é com VTD.","Correta.","Não há ação sobre o próprio sujeito.","Não liga orações.","“Precisar” não é verbo pronominal."]],"1m6dzq4":["Agente da passiva.","",["Não completa verbo transitivo indireto.","Correta.","Não indica circunstância, mas quem praticou a ação.","Não completa um nome.","O sujeito é “o projeto”."]],"dphdjf":["Vocativo: chamamento.","",["O sujeito é “eu”, oculto.","Não explica outro termo.","Correta.","O objeto é “a palavra”.","Não caracteriza o sujeito."]],"1l8jqgu":["Complemento nominal: completa o substantivo “confiança”.","",["Não completa o verbo.","Correta.","A equipe recebe a confiança (valor paciente).","Não indica circunstância.","Não está na voz passiva."]],"1i9qnt8":["Explicativa: entre vírgulas.","",["A restritiva vem sem vírgulas.","Correta.","É adjetiva, ligada ao substantivo “candidatos”.","Não indica circunstância.","É subordinada."]],"1io6e27":["Verbo-nominal: verbo + predicativo.","",["Tem também predicativo.","Tem também verbo significativo.","Correta.","Existe predicado.","Não é classificação de predicado."]],"rkfacl":["Indeterminado: 3ª pessoa do plural sem referente.","",["Não há como identificá-lo.","Correta.","Não há núcleo expresso.","O verbo “roubar” tem sujeito.","Não há núcleos expressos."]],"knvqaj":["No singular, por ser impessoal.","",["Impessoal não vai ao plural.","Correta.","“Anos” não é sujeito.","Não é infinitivo.","Não é subjuntivo."]],"5qln3i":["Substantiva subjetiva: funciona como sujeito.","",["Não se refere a substantivo anterior.","Correta.","Não indica causa.","É subordinada.","Não é objeto: “é importante” é verbo de ligação + predicativo."]],"1kbgj1z":["Coordenadas.","",["Subordinadas dependem da principal.","Correta.","Reduzidas são subordinadas sem conectivo.","A principal se liga à subordinada.","Adjetivas são subordinadas."]]},"tipologia":{"1ejm6yv":["O tipo injuntivo (ou instrucional) diz ao leitor o que fazer, com verbos no imperativo (“misture”, “aperte”) ou no infinitivo (“misturar”, “apertar”). Aparece em manuais, receitas, regulamentos e placas.",""],"eeqfpn":["TIPO é o modo de organizar o texto (narrar, descrever, expor, argumentar, instruir). Existem poucos tipos. GÊNERO é o texto concreto que circula na sociedade (notícia, receita, ofício, bula), e existem milhares.","Tipo = como o texto se organiza. Gênero = o que o texto é no mundo."],"yxefn7":["O texto defende uma posição (precisamos de mais fiscalização), e os dados servem de prova. Isso é argumentação. Os números são argumentos, e não apenas informação.",""],"ivkpcz":["Verbos de ação no passado e marcadores de tempo (“depois”, “em seguida”) são marcas da NARRAÇÃO. A descrição usa adjetivos, verbos de estado (ser, estar, parecer) e o pretérito imperfeito.",""],"1egplkp":["O editorial é a voz do jornal e não traz assinatura. O artigo de opinião é assinado por um autor, que responde pelo que escreve.",""],"1hxqqvv":["A notícia relata o fato de forma objetiva e rápida. A reportagem aprofunda o tema, com contexto, dados, entrevistas e diferentes pontos de vista.",""],"c0ukpd":["Todo gênero mistura tipos. O que define a classificação é o tipo predominante.",""],"1tl8ac":["O texto expositivo apresenta e explica informações, sem defender opinião (exemplo: verbete de enciclopédia). Quem procura convencer é o argumentativo.",""],"7hk4px":["Elementos da narrativa: narrador, personagens, enredo, tempo e espaço.",""],"f4fjba":["É como uma fotografia em palavras: mostra como algo é, sem progressão de tempo.",""],"2sa6xf":["Estrutura: tese (o que se defende), argumentos (as provas) e conclusão.",""],"1kd8mce":["Também chamado dissertativo-expositivo. Exemplos: aula, verbete, relatório técnico.",""],"h2vdh7":["Exemplos: manuais, receitas, bulas (parte de posologia), regulamentos.",""],"13aojrf":["Tipo é a estrutura (narrativa, descritiva etc.); gênero é a forma social (notícia, ofício, receita).",""],"179a47c":["São textos concretos com função social. Cada um pode conter vários tipos.",""],"169gl1p":["Exemplo: uma crônica pode narrar um fato, descrever o lugar e terminar com uma opinião.",""],"fxvl7o":["O “modo de preparo” orienta ações: “bata os ovos”, “leve ao forno”. A lista de ingredientes é descritiva.",""],"36xk77":["É predominantemente argumentativo.",""],"6jlkdk":["Relata o fato (o quê, quem, quando, onde, como, por quê) de forma objetiva e impessoal.",""],"1aln496":["A bula informa (composição, indicações: expositivo) e orienta (como usar: injuntivo). Não conta uma história.",""],"19wmw5p":["Costuma aparecer na introdução, e os parágrafos seguintes trazem os argumentos.",""],"3oji7y":["Exemplo: “Segundo a OMS, o uso do cinto reduz em 50% o risco de morte”.",""],"wtznuh":["Exemplo: citar uma cidade que reduziu acidentes depois de instalar radares.",""],"b7mk8l":["Exemplo: “A rua era estreita e escura; as casas pareciam abandonadas.”",""],"rkhtav":["Observador: conta de fora (“Ele saiu”). Personagem: participa da história (“Eu saí”). Há também o narrador onisciente, que sabe tudo, até os pensamentos dos personagens.",""],"1ph9n5g":["Exemplo: Ele disse: — Estou cansado. Usa verbo de elocução (disse, perguntou) e travessão ou aspas.",""],"jkj5rz":["Exemplo: “Ele disse que estava cansado.” A fala vira oração subordinada, geralmente com “que” ou “se”.",""],"buuryv":["O pensamento ou a fala do personagem aparece dentro da narração, sem travessão e sem verbo de elocução. Exemplo: “Ele olhou o relógio. Meu Deus, já era tarde!”",""],"fr3lhj":["Quando o verbo de elocução está no passado (“disse”), o presente passa ao pretérito imperfeito: “Estou cansado” → “disse que estava cansado”.",""],"gxpaa6":["“Estou” (presente) vira “estava” (imperfeito), e a 1ª pessoa vira 3ª.",""],"184h5rt":["Parte de um fato do dia a dia e pode misturar narração, descrição e opinião, muitas vezes com humor ou reflexão.",""],"1q1tl6c":["É predominantemente argumentativo, e a responsabilidade pela opinião é de quem assina.",""],"ig67vo":["Introdução (tema e tese), desenvolvimento (argumentos) e conclusão (retomada ou proposta).",""],"idefgw":["Orienta o leitor a usar ou montar algo, passo a passo.",""],"12fy72b":["É a comunicação oficial entre órgãos públicos ou destes com particulares, no padrão ofício do Manual de Redação da Presidência.",""],"be8nx":["Usa desenho e texto para criticar ou satirizar um fato atual, geralmente político.",""],"1kzrosp":["Vai além da notícia, que só relata o fato.",""],"e9ff6q":["Narrativo.","",["O descritivo retrata, sem sequência de fatos.","Correta.","O injuntivo dá instruções.","O expositivo informa.","O argumentativo defende uma tese."]],"17o6dwe":["Injuntiva: orienta o modo de fazer.","",["Não conta uma história.","Só a lista de ingredientes é descritiva.","Correta.","Não defende tese.","Não é poesia."]],"1jctjq7":["Editorial.","",["A notícia relata fatos.","Correta.","A reportagem aprofunda um tema, sem ser a voz do jornal.","O classificado é anúncio.","Não é a opinião do jornal."]],"1ryhvu0":["Indireto: o narrador relata a fala.","",["O direto reproduziria a fala com travessão.","Correta.","O indireto livre não tem verbo de elocução.","Não é tipo de discurso.","Não é tipo de discurso."]],"1rt3x":["O ponto de vista defendido.","",["O título nem sempre traz a tese.","Correta.","A conclusão retoma a tese, mas nem sempre é ela.","O exemplo é argumento.","A citação é argumento."]],"qucwe0":["“Ele disse que faria o trabalho”: futuro do presente vira futuro do pretérito.","",["O “eu” deve virar 3ª pessoa.","Correta.","Com “disse”, o futuro vira “faria”.","Muda o tempo de “disse”.","Não é discurso indireto."]],"1v1fbmv":["Autoridade.","",["Correta.","Exemplificação usa casos concretos.","Causa e consequência mostra efeitos.","Comparação aproxima situações.","Senso comum usa crenças populares."]],"1gonsy7":["A forma concreta de texto usada socialmente.","",["Estrutura abstrata é o tipo.","Correta.","Não são sinônimos.","Inclui textos não literários.","Inclui textos escritos."]],"1rce5fo":["Descritivo.","",["Narrativo tem verbos de ação.","Correta.","Injuntivo tem imperativos.","Argumentativo tem conectores e opinião.","Expositivo tem informação."]],"1ohersl":["1ª pessoa.","",["Correta.","A 2ª pessoa é rara e não é a marca do narrador-personagem.","3ª pessoa é o observador.","Há marcas de pessoa.","Pode ser singular."]],"14c5cm7":["Expositivo e injuntivo: informa e orienta.","",["Não narra.","Correta.","Não é poética.","Não narra.","Não é lírica."]],"bljets":["Indireto livre.","",["O direto tem travessão.","O indireto tem verbo de elocução e “que”.","Correta.","Não é tipo de discurso.","Não é tipo de discurso."]],"8phfpa":["Expositivo.","",["O argumentativo defende opinião.","Correta.","O injuntivo dá instruções.","O poético tem função estética.","O opinativo defende opinião."]]}};
